    private val part1 = listOf(
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 1, text = "Apre li te fin kraze moun Amalèk yo, David tounen lavil Ziklag. Lè sa a Sayil te deja mouri. David menm te lavil Ziklag depi de jou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 2, text = "Sou twazyèm jou a, yon nonm rive soti nan kan Sayil la. Rad sou li te chire, li te gen pousyè sou tèt li pou fè wè jan li te nan gwo lapenn. Lè li rive bò kote David, li lage kò l' atè, li bese tèt li byen ba devan li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 3, text = "David mande l': -Kote ou soti? Nonm lan reponn: -Mwen chape kò m' soti nan kan moun Izrayèl yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 4, text = "David di li: -Manyè di m' sa ki pase. Nonm lan reponn: -Lame pèp Izrayèl la kouri pandan batay la te mare. Gen anpil sòlda ki mouri. Sayil ak Jonatan, pitit gason l' lan, mouri tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 5, text = "David mande nonm ki te pote nouvèl la: -Ki jan ou fè konnen Sayil ak Jonatan, pitit li a, mouri?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 6, text = "Nonm lan reponn: -Mwen t'ap pase konsa sou mòn Gilboa a lè mwen wè Sayil apiye sou frenn li pou l' pa tonbe atè. Cha lagè lènmi yo ak kavalye yo te prèt pou rive sou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 7, text = "Lè sa a, li voye je l' gade, li wè m', epi li rele m' vini. Mwen reponn li: Men mwen, monwa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 8, text = "Li mande m' ki moun mwen ye. Mwen reponn li se yon moun Amalèk mwen ye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 9, text = "Lè sa a, li mande m' pou m' pwoche bò kote l' pou m' touye l', paske li te santi tèt li ap vire, atout li te gen tout konesans li sou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 10, text = "Se konsa, mwen pwoche bò kote l', mwen touye l' paske mwen te konnen tonbe li te tonbe li t'ap toujou mouri. Apre sa, mwen pran kouwòn ki te sou tèt li ak braslè ki te nan ponyèt li, mwen pote yo ba ou, mèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 11, text = "David chire rad ki te sou li sitèlman sa te fè li lapenn. Tout moun ki te la avè l' yo fè menm bagay la tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 12, text = "Yo kriye, yo pran gwo lapenn pou Sayil, pou Jonatan, pitit li a, pou lame Seyè a ak pou pèp Izrayèl la, paske te gen anpil ladan yo ki te mouri nan lagè a. Yo rete san manje jouk aswè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 13, text = "Apre sa, David mande jenn gason ki te pote nouvèl la: -Ki moun ou ye? Jenn gason an reponn: -Mwen se pitit yonn nan moun Amalèk ki vin rete nan peyi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 14, text = "David di l' konsa: -Bon. Ki jan ou fè pa t' pè leve men ou sou wa Bondye chwazi a pou ou rive touye l'?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 15, text = "David rele yonn nan moun li yo. Li di l' konsa: -Vini non! Touye msye. Nonm lan bay moun Amalèk la yon sèl kou, li touye l' frèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 16, text = "David menm te di moun Amalèk la: -Se ou menm ki reskonsab sa ki rive ou la a. Se ou menm ki kondannen tèt ou lè ou di ak bouch ou se ou menm ki touye wa Bondye te chwazi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 17, text = "David pran chante pou plenn lanmò Sayil ak Jonatan, pitit Sayil la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 18, text = "Li bay lòd pou yo moutre chante a bay tout moun Jida yo. Se chante banza yo. Yo jwenn li ekri nan Liv Moun ki mache dwat la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 19, text = "O Izrayèl, tout gwo chèf ou yo mouri sou mòn yo. Yo desann tout vanyan sòlda ou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 20, text = "Pa kite nouvèl la rive nan lavil Gad. Pa gaye nouvèl la nan lavil Askalon, pou medam peyi Filisti yo pa fè fèt, pou pitit fi moun sa yo ki pa sèvi Bondye pèp Izrayèl la pa leve danse.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 21, text = "Nou menm mòn Giboa yo, se pou nou rete san yon grenn lapli, san yon degout lawouze. Piga jaden janm pouse sou flan mòn nou yo! Paske se la yo trennen nan labou plak fè pwotèj sòlda yo, plak fè pwotèj wa Sayil la ki p'ap janm fwote ak lwil ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 22, text = "Jonatan pa t' janm fè bak toutotan li pa tranpe flèch li yo nan san lènmi l' yo. Sayil pa t' janm tounen toutotan li pa t' plonje nepe l' nan vant vanyan sòlda lènmi l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 23, text = "Sayil ak Jonatan, yonn te renmen lòt! Toujou ansanm nan lavi, ansanm ansanm tou nan lanmò! Pi veyatif pase malfini, pi vanyan pase lyon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 24, text = "Medam pèp Izrayèl yo, rele pou Sayil! Li te konn ban nou bèl rad koulè violèt ki koute byen chè, ak bèl bijou an lò pou mete sou nou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 25, text = "Vanyan sòlda yo mouri nan lagè! Jonatan mouri, li blayi atè plat sou ti mòn yo!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 26, text = "Mwen gen gwo lapenn pou ou, Jonatan, frè mwen. Jan mwen te renmen ou sa a! Jan ou menm ou te renmen m', se pa pale. Zanmitay sa a te pi bon pou mwen lontan pase renmen ankenn fanm ta ka gen pou mwen!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 1, verseNumber = 27, text = "Vanyan sòlda yo mouri! Tout zam lagè yo pa vo anyen koulye a!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 1, text = "Apre sa, David mande Seyè a: -Eske se pou m' ale nan yonn nan lavil peyi Jida yo? Seyè a reponn li: -Wi. Se pou ou ale! David mande l': -Kote pou m' ale? Seyè a di l': -Lavil Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 2, text = "Se konsa, David pran de madanm li yo, Akenoam ki te moun lavil Jizreyèl, ak Abigayèl, vèv Nabal la, ki te moun lavil Kamèl, li pati pou Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 3, text = "Li mennen moun ki te avè l' yo tou ansanm ak tout fanmi yo. Y' al rete lavil Ebwon ak nan tout ti bouk ki toupre l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 4, text = "Apre sa, moun Jida yo rive lavil Ebwon, yo fè seremoni pou mete David apa pou sèvi wa peyi Jida. David vin pran nouvèl se moun lavil Jabès yo, nan peyi Galarad, ki te antere Sayil.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 5, text = "Lè sa a, li voye kèk mesaje di yo konsa: -Se pou Seyè a beni nou, paske nou moutre jan nou pa janm lage Sayil, mèt nou an. Nou antere l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 6, text = "Mwen mande Seyè a pou li aji byen ak nou tou, pou li pa janm lage nou. Mwen menm pou tèt pa m', m'ap aji byen avèk nou tou poutèt sa nou fè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 7, text = "Koulye a, pran kouraj! Mete gason nou nou! Sayil, mèt nou an, mouri. Se mwen menm moun Jida yo mete apa pou wa yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 8, text = "Abnè, pitit gason Nè a, kòmandan lame Sayil la, pran Ichbochèt, pitit gason Sayil la, li mennen l' lavil Manayim, lòt bò larivyè Jouden.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 9, text = "Rive la, li nonmen Ichbochèt wa peyi Galarad, peyi Asè, peyi Jizreyèl, peyi Efrayim ak peyi Benjamen, ki vle di wa tout pèp Izrayèl la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 10, text = "Ichbochèt, pitit gason Sayil la, te gen karantan lè yo fè l' wa peyi Izrayèl. Li gouvènen pandan dezan. Men, moun branch fanmi Jida yo te kanpe avèk David.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 11, text = "David te wa peyi Jida a pandan sètan sis mwa. Se Ebwon li te rete.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 12, text = "Abnè leve ansanm ak moun Ichbochèt yo, yo kite lavil Manayim, y' ale lavil Gabawon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 13, text = "Joab menm, pitit gason Sewouya a, leve ansanm ak sòlda David yo, yo kite lavil Ebwon, yo pati tou. Yo kontre ak moun Abnè yo bò rezèvwa Gabawon an. De lame yo pran pozisyon, yonn chak bò rezèvwa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 14, text = "Abnè di Joab konsa: -Annou chwazi kèk jenn gason pou yo goumen devan nou la a. Joab reponn: -Dakò!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 15, text = "Se konsa, douz gason nan branch fanmi Benjamen an kanpe pou Ichbochèt yon bò, douz gason kanpe pou moun David yo lòt bò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 16, text = "Mesye yo mare goumen. Yonn pran lòt nan tèt epi yonn foure nepe yo nan kò lòt. Se konsa yo tout tonbe ansanm, yo mouri. Se poutèt sa, yo rele kote sa a nan peyi Gabawon an Elkatazourim.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 17, text = "Apre sa, yon gwo batay pete. Moun David yo kraze Abnè ansanm ak moun Izrayèl yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 18, text = "Tou twa pitit gason Sewouya yo te la. Se te Joab, Abichayi ak Asayèl. Asayèl te konn kouri, ou ta di yon ti kabrit mawon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 19, text = "Li pran kouri pye pou pye dèyè Abnè ki t'ap chache chape kò l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 20, text = "Abnè vire tèt li gade dèyè. Li di: -Se pa ou menm sa, Asayèl? Asayèl reponn li: -Men wi, se mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 21, text = "Abnè di l' konsa: -Sispann kouri dèyè m'. Pito ou kouri dèyè yonn nan sòlda yo. Lèfini, w'a pran tou sa li genyen. Men, Asayèl pa t' vle sispann kouri dèyè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 22, text = "Yon dezyèm fwa Abnè di l': -Asayèl, m' di ou sispann kouri dèyè m' wi! Pa fòse m' touye ou! Apre sa, ki jan m'a fè pou m' parèt devan Joab, frè ou la?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 23, text = "Men, Asayèl pa t' vle sispann kouri dèyè l'. Lè sa a, Abnè ba li yon kou nan vant ak pwent dèyè frenn li an. Frenn lan travèse Asayèl, li soti nan do l'. Asayèl tonbe atè, li mouri frèt. Lè tout moun rive kote li te tonbe a yo rete la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 24, text = "Men Joab ak Abichayi pran kouri pi rèd dèyè Abnè. Solèy tapral kouche lè yo rive sou ti bit mòn Anma a, ki sou bò solèy leve lavil Giyak, sou chemen ki mennen nan dezè Gabawon an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 25, text = "Moun branch fanmi Benjamen yo sanble bò kote Anbè ankò. Yo pran pozisyon pou yo goumen sou tèt yon ti mòn.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 26, text = "Abnè rele Joab, li di l' konsa: -Gen lè nou p'ap janm fini ak batay sa a? Ou pa wè sa ap fini mal pou nou tou de? Se frè nou ye. Sa w'ap tann pou ou bay moun ou yo lòd pou yo sispann kouri dèyè nou?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 27, text = "Joab reponn li: -Mwen pran Bondye ki vivan an pou temwen. Si ou pa t' pale konsa se denmen maten moun pa m' yo t'ap sispann kouri dèyè ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 28, text = "Joab fè kònen klewon. Tout moun li yo rete sou sa yo te fè, yo sispann kouri dèyè moun Izrayèl yo. Se konsa batay la fini.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 29, text = "Abnè ak moun pa l' yo mache nan fon Jouden an tout lannwit lan. Lèfini, yo janbe lòt bò larivyè Jouden an. Yo travèse tout zòn Bitwon an jouk yo rive lavil Manayim.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 30, text = "Joab menm, lè li sispann kouri dèyè Abnè a, li sanble tout lame a. Te gen disnèf sòlda nan moun David yo ki pa t' reponn prezan san konte Asayèl.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 31, text = "Patizan David yo te touye twasanswasant (360) nan patizan Abnè yo, tout nan branch fanmi Benjamen an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 2, verseNumber = 32, text = "Joab ak moun pa l' yo pran kadav Asayèl, y' al antere l' nan tonm fanmi an lavil Betleyèm. Apre sa, yo pase nwit lan ap mache. Solèy t'ap leve lè yo rive Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 1, text = "Patizan fanmi Sayil yo ak patizan David yo pase lontan ap goumen yonn ak lòt konsa. Men, patizan David yo t'ap vin pi plis chak jou. Patizan fanmi Sayil yo menm t'ap bese.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 2, text = "Men sis pitit gason David vin fè antan li te lavil Ebwon: Pi gran an te rele Amon. Se Akenoam, moun lavil Jizreyèl, ki te manman l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 3, text = "Dezyèm lan te rele Kileyab. Se Abigayel, vèv Nabal la, moun lavil Kamèl, ki te manman l'. Twazyèm lan te rele Absalon. Se Maka, pitit fi Talmayi, wa lavil Gechou a, ki te manman l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 4, text = "Katriyèm lan te rele Adonija. Se Agit ki te manman l'. Senkyèm lan te rele Chefatya. Se Abital ki te manman l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 5, text = "Sizyèm lan te rele Jitreyam. Se Egla, yon lòt madanm David te genyen, ki te manman l'. Yo tout te fèt antan David te rete lavil Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 6, text = "Pandan lagè a t'ap kaye ant patizan fanmi Sayil yo ak patizan David yo, Abnè te vin gen plis pouvwa chak jou sou patizan fanmi Sayil yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 7, text = "Sayil te gen yon fanm kay ki te rele Rispa. Se te pitit fi Aja. Abnè te kouche avè l'. Yon jou, Ichbochèt rele Abnè, li di l' konsa: -Poukisa w' al kouche avèk yonn nan fanm kay papa m' yo?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 8, text = "Lè Abnè tande sa, li fache anpil. Li di Ichbochèt konsa: -Eske se yon chen k'ap travay pou moun Jida yo mwen ye? Jouk jounen jòdi a mwen pa janm trayi Sayil, papa ou, ni patizan l' yo, ni zanmi l' yo. Mwen goumen rèd mare pou m' pa kite yo tonbe nan men David. Lèfini, pou koulye a w'ap fè m' repwòch pou yon ti pachat mwen te fè ak fanm sa a!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 9, text = "Se pou Seyè a ban m' pi gwo pinisyon ki genyen si mwen pa fè pwomès Bondye te fè David la rive vre.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 10, text = "Paske li te fè sèman l'ap wete baton kòmandman an nan fanmi Sayil la pou l' mete David wa sou moun Izrayèl yo ak sou moun Jida yo, soti depi teritwa Dann lan rive teritwa Becheba a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 11, text = "Ichbochèt pa t' ka reponn Abnè anyen sitèlman li te pè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 12, text = "Abnè voye kèk mesaje bò kote David pou di li: -Ki moun ki pral gouvènen peyi sa a? Pase yon kontra avè m'. M'ap ede ou pou tout moun Izrayèl yo vin jwenn ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 13, text = "David reponn li: -Dakò. M'ap pase yon kontra avè ou. Men, m'ap mande yon sèl bagay. Piga ou vin wè m' san ou pa mennen Mikal, pitit fi Sayil la, avè ou. Se sèl jan pou ou parèt devan m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 14, text = "Apre sa, David voye kèk mesaje bò kot Ichbochèt pou di li: -Renmèt mwen Mikal, madanm mwen. Mwen te bay san po ti kòk moun Filisti pou m' te ka marye avè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 15, text = "Ichbochèt voye pran Mikal lakay mari li, Paltyèl, pitit gason Layis la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 16, text = "Paltyèl pati dèyè l', li t'ap kriye sou tout wout la jouk yo rive lavil Baourim. Men Abnè di Paltyèl konsa: -Tounen lakay ou non, monchè! Epi Paltyèl tounen tounen l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 17, text = "Abnè al jwenn chèf fanmi moun Izrayèl yo pou fè yon koze ak yo. Li di yo konsa: -Depi lontan nou te vle se David ki pou te wa nou, pa vre.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 18, text = "Enben, men chans nou. Paske men sa Seyè a te di sou David: Mwen pral sèvi ak David, sèvitè m' lan, pou m' delivre pèp Izrayèl la, pèp mwen an, anba men moun Filisti yo ak anba men tout lòt lènmi l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 19, text = "Anbè pale ak moun branch fanmi Benjamen yo tou. Lèfini, li pati pou Ebwon pou li al di David sa moun pèp Izrayèl yo ansanm ak tout moun branch fanmi Benjamen yo te tonbe dakò pou yo fè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 20, text = "Li rive lakay David lavil Ebwon. Li te gen vin lòt gason avè l'. David fè yon gwo resepsyon pou Abnè ak pou vin moun ki te avè l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 21, text = "Abnè di David konsa: -Monwa, mwen prale koulye a, mwen pral sanble tout moun pèp Izrayèl yo bò kote ou. y'a pase yon kontra avè ou. Konsa, w'a ka gouvènen tout peyi a jan ou vle l' la. David bay Abnè pèmisyon pou li ale. Lèfini, Abnè pati ak kè poze.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 22, text = "Apre sa, Joab ak patizan David yo vin rive. Yo te sot fè yon pase kay lènmi yo, yo te tounen ak anpil bagay yo te pran lakay yo. Lè sa a, Abnè pa t' Ebwon ankò lakay David, paske David te gen tan kite l' ale ak garanti anyen p'ap rive l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 23, text = "Lè Joab ak sòlda ki te avè l' yo rive, yo di Joab Abnè, pitit Nè a, te vin wè wa a, epi wa a kite l' ale ak garanti anyen p'ap rive l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 24, text = "Joab al jwenn wa a, li di li: -Sa ou fè konsa? Abnè vin jwenn ou epi ou kite l' ale san ou pa fè l' anyen?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 25, text = "Ou konn ki moun yo rele Abnè, pitit Nè a! Si li vini, se pou l' ka woule ou, pou l' ka konnen tout vire tounen ou, pou l' konnen tou sa w'ap fè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 26, text = "Lèfini, Joab soti kay David, li voye moun al chache Abnè san David pa konnen. Yo jwenn Abnè bò sitèn dlo Sira a, yo fè l' tounen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 27, text = "Lè Abnè rive Ebwon, Joab mennen l' apa bò pòtay lavil la tankou si li te vle pale pou kont li avè l'. Epi li ba li yon kout ponya nan vant. Se konsa Joab touye Abnè paske Abnè te touye Asayèl, frè l' la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 28, text = "Lè David vin pran nouvèl la, li di: -Seyè a wè ni mwen ni moun gouvènman yo, nou pa gen anyen pou nou wè nan lanmò Abnè, pitit Nè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 29, text = "Se pou chatiman an tonbe sou tèt Joab ak tout fanmi li! Se pou toujou gen nan fanmi li moun k'ap gen ekoulman osinon move maladi po, gason k'ap blije fè travay fanm, gason k'ap mouri nan lagè, gason k'ap nan grangou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 30, text = "Se konsa, Joab ak Abichay, frè l' la, te ansasinen Abnè paske Abnè te touye Asayèl, frè yo a, lè batay Gabawon an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 31, text = "Apre sa, David bay Joab ak tout moun ki te avè l' yo lòd pou yo chire rad ki sou yo, pou yo mete rad sak sou yo, lèfini pou yo mache devan sèkèy Abnè a ap kriye. Wa David menm t'ap mache dèyè sèkèy defen an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 32, text = "Yo antere Abnè Ebwon. Apre sa, wa a pran rele byen fò, li t'ap kriye sou tonm Abnè a. Tout pèp la t'ap kriye tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 33, text = "Wa a pran chante pou plenn lanmò Abnè. Li di nan chante a: -Abnè, poukisa ou mouri bèt konsa?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 34, text = "Men ou yo pa t' mare, pye ou yo pa t' nan chenn. Ou mouri tankou moun ki tonbe nan men malfektè! Tout pèp la pran kriye ankò pou Abnè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 35, text = "Apre sa, pandan tout rès jounen an, yo pote manje bay David pou li manje, men David fè sèman sa a: -Se pou Bondye ban m' pi gwo pinisyon ki genyen si mwen mete anyen nan bouch mwen anvan solèy kouche!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 36, text = "Tout pèp la vin konn sa. Sa te fè yo plezi. Pou di vre, tou sa David te fè te fè pèp la plezi.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 37, text = "Se konsa tout moun David yo ansanm ak tout moun pèp Izrayèl yo te vin konnen tout bon vre wa a pa t' gen anyen pou l' te wè nan jan yo te ansasinen Abnè, pitit gason Nè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 38, text = "Wa a di moun k'ap sèvi avè l' yo: -Aa, mesye! Jòdi a pèp Izrayèl la pèdi yon chèf, yon gwo chèf wi!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 3, verseNumber = 39, text = "Atout se wa Bondye chwazi a mwen ye, mwen santi m' fèb jòdi a. Pitit gason Sewouya yo twò mechan pou mwen. Se pou Bondye pini krimenèl sa yo pou mechanste yo fè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 1, text = "Lè Ichbochèt, pitit Sayil la, pran nouvèl jan Abnè te mouri lavil Ebwon, kè l' kase nèt. Tout pèp Izrayèl la te tèt anba.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 2, text = "Ichbochèt te gen nan lame li a de chèf piyajè ki te rele Bana ak Rekab. Yo te pitit Rimon, yon nonm nan branch fanmi Benjamen an ki te rete lavil Bewòt. Yo te toujou mete nan tèt yo lavil Bewòt se pou branch fanmi Benjamen an li ye,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 3, text = "depi lè moun Bewòt yo te kouri kite lavil la pou y' al lavil Gitayim, kote y'ap viv jouk koulye a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 4, text = "Jonatan, pitit Sayil la, te gen yon pitit gason yo te rele Mefibochèt. Li te enfim nan tou de pye l' yo. Li te gen senkan lè Sayil ak Jonatan mouri. Lè nouvèl lanmò yo rive soti lavil Jizreyèl, nouris la pran Mefibochèt, li kouri al kache avè l'. Men, pandan l'ap prese kouri a, pitit la sot tonbe nan men l'. Se konsa li vin enfim nan pye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 5, text = "Rekab ak Bana, pitit gason Rimon, moun lavil Bewòt la, pati pou lakay Ichbochèt. Yo rive vè midi. Lè sa a, Ichbochèt t'ap fè yon ti dòmi pou poze kò l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 6, text = "Fanm ki t'ap veye bò pòt la t'ap triye ble, men li te kite dòmi pran l'. Se konsa mesye yo fofile kò yo antre nan kay la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 7, text = "Lè yo rive anndan, y' al nan pyès chanm kote Ichbochèt te kouche ap dòmi an, yo touye l'. Lèfini, yo koupe tèt li, yo pran l', yo pati avè l'. Yo pase nwit lan ap mache nan fon Jouden an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 8, text = "Yo pote tèt Ichbochèt bay David lavil Ebwon. Yo di l' konsa: -Men tèt Ichbochèt, pitit Sayil la, moun ki pa t' vle wè ou la, moun ki t'ap chache touye ou la. Jòdi a Seyè a bay monwa chans pou li tire revanj sou Sayil ansanm ak sou rès fanmi li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 9, text = "David reponn yo: -Mwen fè sèman devan Seyè a ki delivre m' nan tout malè,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 10, text = "lè moun ki te vin fè m' konnen Sayil te mouri a te kwè se yon bon nouvèl li t'ap pote ban mwen, mwen pran l', mwen fè touye l' lavil Ziklag. Men rekonpans mwen te ba li pou bon nouvèl sa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 11, text = "Sa pral pi rèd toujou pou nou, bann mechan, ki touye yon inonsan anndan lakay li, nan kabann li. Mwen pral fè nou peye pou touye nou touye l' la, mwen pral fè yo disparèt nou sou latè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 4, verseNumber = 12, text = "David bay sòlda yo lòd epi yo touye Rekab ak Bana. Yo koupe de men ak de pye yo. Y' al pann yo bò rezèvwa dlo Ebwon an. Apre sa, yo pran tèt Ichbochèt, y' al antere l' Ebwon, nan tonm Abnè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 1, text = "Tout branch fanmi Izrayèl yo vin jwenn David lavil Ebwon, yo di l' konsa: -Nou se moun menm ras, menm fanmi avè ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 2, text = "Depi lontan, menm sou rèy Sayil, se ou menm ki te kòmande lame pèp Izrayèl la kote l' pase. Lèfini ankò, Seyè a te pwomèt se ou menm ki pral gouvènen pèp li a, pèp Izrayèl la, se ou menm ki pral chèf yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 3, text = "Se konsa tout chèf fanmi pèp Izrayèl yo vin jwenn David lavil Ebwon. Yo pase yon kontra avè l' devan Seyè a. Yo fè seremoni, yo mete l' wa sou pèp Izrayèl la tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 4, text = "David te gen trantan lè l' rive wa. Li kòmande pandan karantan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 5, text = "Antan lavil Ebwon, li kòmande moun Jida yo pandan sètan simwa. Lavil Jerizalèm, li kòmande ni moun pèp Izrayèl yo ni moun pèp Jida yo pandan tranntwazan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 6, text = "Apre sa, wa David pati pou lavil Jerizalèm ansanm ak sòlda li yo, li al atake moun Jebis yo ki te rete nan zòn sa a. Moun Jebis yo te konprann David pa ta ka antre pran lavil la. Yo di l' konsa: -Ou p'ap janm ka rive antre nan lavil nou an. Ata moun je pete ak moun enfim ka gen kont fòs pou mete ou deyò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 7, text = "Men, David pran gwo fò ki te sou tèt mòn Siyon an. Se li yo rele lavil David la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 8, text = "Jou sa a, David te di moun pa li yo: -Tout moun ki vle atake moun Jebis yo va pase nan kannal la, y'a tonbe sou bann enfim ak je pete sa yo ki pa vle wè m' yo. Se depi lè sa a yo di moun je pete ak moun enfim pa gen dwa mete pwent pye yo nan Tanp Seyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 9, text = "Apre sa, David al rete nan gwo fò a, li rele l' lavil David la. Lèfini, li bati lòt kay fè wonn fò a, depi sou teras la rive bò palè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 10, text = "Chak jou David t'ap vin pi fò. Seyè a, Bondye ki gen tout pouvwa a, te avè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 11, text = "Se konsa, Iram, wa lavil Tir la, delege kèk mesaje bò kot David ak yon chajman bwa sèd. Li voye tou kèk bòs chapant ak bòs mason ki bati yon palè pou David.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 12, text = "Lè sa a atò, David wè tout bon vre se Seyè a menm ki te mete l' wa pèp Izrayèl la. Se li menm menm ki te fè tout bagay mache byen pou gouvènman li a, akòz pèp li a, pèp Izrayèl la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 13, text = "Lè David kite lavil Ebwon pou li al lavil Jerizalèm, rive la li pran lòt madanm ak lòt fanm kay ki ba li lòt pitit gason ak lòt pitit fi.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 14, text = "Men jan yo te rele pitit David ki te fèt lavil Jerizalèm yo: Chamwa, Chobab, Natan, Salomon,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 15, text = "Jibka, Elichwa, Nefèg, Jafya,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 16, text = "Elichama, Elyada ak Elifelèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 17, text = "Lè moun Filisti yo vin konnen yo te mete David wa pèp Izrayèl la, yo tout yo leve pou y' al mete men sou li. Lè David pran nouvèl la, li desann al kache nan yon fò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 18, text = "Moun Filisti yo rive, yo pran tout fon Refayim lan pou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 19, text = "David pale ak Seyè a, li mande l': -Eske se pou m' atake moun Filisti yo? Eske w'ap lage yo nan men m'? Seyè a reponn li: -Wi, atake yo. M'ap lage yo nan men ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 20, text = "David ale Baal Perazim.li bat moun Filisti yo. Lèfini, li di: -Tankou yon lavalas, Seyè a pase, li louvri yon pasaj pou mwen nan mitan lènmi m' yo. Se poutèt sa yo rele kote sa a Baal Perazim.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 21, text = "Moun Filisti yo te kouri kite zidòl yo dèyè nan plenn lan. David ak moun pa l' yo pran yo pote ale.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 22, text = "Moun Filisti yo tounen nan fon Refayim lan, yo pran tout plenn lan pou yo ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 23, text = "David mande Seyè a sa pou l' fè. Seyè a di l': -Pa atake yo pa devan. Pase pa dèyè yo. Pare kò ou pou ou atake yo bò pye gayak yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 24, text = "Lè w'a tande yon bri tankou bri pye yon moun k'ap mache sou tèt pyebwa yo, w'a fonse sou yo. Paske sa vle di m'ap pran devan ou pou m' bat lame moun Filisti yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 5, verseNumber = 25, text = "David fè sa Seyè a te mande l' fè a. Li bat moun Filisti yo, li kouri dèyè yo depi Lavil Gebarive lavil Gezè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 1, text = "Yon lòt fwa ankò, David reyini tout pi bon sòlda pèp Izrayèl la. Sa te fè antou trantmil (30.000) gason.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 2, text = "Li leve, li pati pou Balat nan peyi Jida ansanm ak tout sòlda ki te avè l' yo. Li tapral chache Bwat Kontra Bondye a, bwat ki pote non Seyè ki gen tout pouvwa a, Seyè ki gen fotèy li anwo zanj cheriben yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 3, text = "Yo pran Bwat la kay Abenadab sou mòn lan, mete l' sou yon kabwa tou nèf, yo pote l' ale. Ouza ak Akiyo, pitit gason Abenadab yo, t'ap mennen kabwa", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 4, text = "kote yo te mete Bwat Kontra Bondye a. Akiyo t'ap mache devan kabwa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 5, text = "David ansanm ak tout moun pèp Izrayèl yo menm t'ap danse ak tout nanm yo. Yo t'ap chante fè lwanj Seyè a. Yo t'ap jwe gita ak bandjo. Yo t'ap bat tanbou, tanbouren ak senbal.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 6, text = "Lè yo rive bò glasi Nakon an, bèf yo bite, yo manke tonbe. Ouza lonje men l', li soutni Bwat Kontra a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 7, text = "Men Seyè a move sou Ouza, li touye l' frèt paske li pa t' gen dwa manyen Bwat Kontra a. Ouza mouri la toupre Bwat Kontra a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 8, text = "David menm te fache dèske Seyè a te touye Ouza konsa. Se poutèt sa depi lè sa a yo rele kote sa a Perèz-Ouza, non ki rete pou li jouk jounen jòdi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 9, text = "Lè sa a, David vin pè Seyè a. Li di li pa wè ki jan pou l' pran Bwat Kontra a lakay li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 10, text = "Se konsa li pran desizyon pou l' pa pote Bwat Kontra Seyè a lakay li nan Lavil David la. Li fè yo pote l' kay Obèdedon, yon moun lavil Gat.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 11, text = "Bwat la pase twa mwa lakay li. Seyè a te beni Obèdedon ansanm ak tout moun lakay li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 12, text = "Lè David tande jan Seyè a te beni Obèdedon ak tout moun lakay li, jan zafè l' t'ap mache byen poutèt Bwat Kontra a, David pati, li ale kay Obèdedon, li pran Bwat Kontra Seyè a pou pote l' nan Lavil David la avèk gwo seremoni sou tout wout la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 13, text = "Lè moun ki t'ap pote Bwat Kontra Seyè a fè sis pa annavan, David fè yo rete, li touye yon gwo towo ak yon ti towo bèf chatre pou Seyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 14, text = "Apre sa, David pran danse ak tout nanm li devan Seyè a. Li pa t' gen pase yon moso twal fen blan mare nan ren l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 15, text = "Se konsa, li menm ak tout pèp Izrayèl la, yo pote Bwat Kontra Seyè a lavil Jerizalèm. Yo t'ap fè fèt, yo t'ap kònen twonpèt sou tout wout la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 16, text = "Antan yo t'ap antre ak Bwat Kontra a nan lavil David la, Mikal, pitit fi Sayil la, te kanpe bò yon fennèt ap gade. Li wè David ki t'ap danse fè laviwonn devan Seyè a. Li vin pa gen yon san pou li ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 17, text = "Yo pote Bwat Kontra Seyè a, yo mete l' nan plas li nan tant David te moute pou li a. Apre sa, David ofri bèt pou boule nèt pou Seyè a ak ofrann pou di Bondye mèsi.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 18, text = "Lè David fin fè ofrann sa yo, li beni pèp la nan non Seyè ki gen tout pouvwa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 19, text = "Li separe manje bay tout moun pèp Izrayèl yo, fanm kou gason. Li ba yo chak yon pen, yon moso vyann woti ak yon pen rezen. Lèfini, tout moun al lakay yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 20, text = "Apre sa, David al lakay li pou l' beni fanmi pa l' tou. Men, Mikal, pitit fi Sayil la, soti vin kontre li. Epi li di l' konsa: -Ala yon bèl bagay wa pèp Izrayèl la fè pou tèt li jòdi a! Tou sa yon vakabon ta fè. Li wete rad sou li devan tout sèvant moun k'ap sèvi avè l' yo!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 21, text = "David reponn li: -Se vre. Mwen t'ap danse pou m' te fè lwanj Seyè a ki te pito m' pase papa ou ak tout fanmi ou. Li chwazi m', li mete m' chèf pèp Izrayèl la, pèp li a. M'ap toujou ka danse devan l' pou m' fè lwanj li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 22, text = "M'ap desanm tèt mwen pi ba toujou pase sa. Dapre ou, se desann m'ap desann sousi m'. Men, sèvant w'ap pale yo ap toujou ka leve m' anlè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 6, verseNumber = 23, text = "Mikal, pitit fi Sayil la, pa janm fè pitit jouk li mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 1, text = "Wa David te byen chita nan palè li. Seyè a te pwoteje l', li te fè tout lènmi ki te alantou peyi a pa chache l' kont ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 2, text = "Wa a pale ak pwofèt Natan, li di l' konsa: -Gade! Mwen rete nan yon kay bati ak bwa sèd, men Bwat Kontra Seyè a se anba yon kay twal li ye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 3, text = "Natan reponn li: -Tou sa ou gen lide fè, ou mèt fè l', paske Seyè a kanpe la avè ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 4, text = "Men, menm jou lannwit sa a, Seyè a pale ak Natan, li di l' konsa:", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 5, text = "-Ale di David, sèvitè m' lan, men sa mwen menm Seyè a, mwen voye di l': Se pa ou menm ki pral bati yon tanp pou m' rete.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 6, text = "Depi jou mwen te fè moun pèp Izrayèl yo soti kite peyi Lejip rive jòdi a, mwen pa janm rete nan yon kay. Tout kote m' pase se anba yon tant twal mwen toujou ye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 7, text = "Nan tout deplase mwen ansanm ak moun Izrayèl yo, mwen pa janm mande yonn nan chèf mwen te chwazi pou gouvènen pèp mwen an poukisa yo pa bati yon kay an bwa sèd pou mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 8, text = "Koulye a, men sa w'a di David, sèvitè m' lan: Men sa Seyè ki gen tout pouvwa a voye di ou: Se mwen menm ki te pran ou dèyè mouton ou t'ap gade nan savann yo, mwen mete ou chèf pèp mwen an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 9, text = "Nan tou sa ou t'ap fè, mwen te kanpe la avè ou. Mwen kraze tout lènmi ou yo devan ou. Mwen pral fè yo nonmen non ou tankou y'ap nonmen non pi gwo chèf ki sou latè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 10, text = "Lèfini, mwen pare yon kote pou pèp Izrayèl mwen an. Mwen pral tabli yo la pou yo ka viv san yo pa bezwen pè anyen ankò. Mechan yo p'ap vin maltrete yo ankò jan yo te konn fè l' anvan an,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 11, text = "lè mwen te mete jij yo pou gouvènen pèp Izrayèl mwen an. M'ap delivre ou anba men tout lènmi ou yo. Mwen te fè ou konnen m'ap ba ou pitit ak pitit pitit.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 12, text = "Lè lè a va rive pou ou mouri, lè y'a antere ou, m'ap pran yonn nan pitit ou yo, m'ap mete l' wa nan plas ou. M'ap fè gouvènman l' lan kanpe fèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 13, text = "Se li menm ki va bati yon tanp pou mwen. M'ap fè gouvènman l' lan kanpe fèm pou tout tan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 14, text = "M'ap yon papa pou li. Li menm l'ap yon pitit pou mwen. Si li fè sa ki mal, m'ap korije l' tankou yon papa korije pitit gason li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 15, text = "Men, m'ap toujou soutni l', mwen p'ap lage l' jan mwen te lage Sayil lè mwen te kite l' tonbe pou m' te mete ou nan plas li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 16, text = "Ap toujou gen moun nan fanmi ou chita sou fotèy la ap gouvènen apre ou, paske m'ap fè gouvènman fanmi ou lan kanpe fèm pou tout tan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 17, text = "Natan rakonte David tou sa Bondye te fè l' konnen nan vizyon an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 18, text = "Apre sa, wa David ale nan tanp lan, li chita devan Seyè a, li di l' konsa: -Seyè, Bondye sèl Mèt la, kisa mwen ye, kisa fanmi mwen ye pou ou te fè tou sa ou deja fè pou nou?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 19, text = "Men ou wè sa pa kont toujou, Seyè, Bondye sèl Mèt la, kifè koulye a w'ap fè konnen sa ki pral rive fanmi mwen denmen nan lanne k'ap vini yo. Epi ou fè m' konn sa, mwen menm ki yon senp moun, Seyè, Bondye sèl Mèt la!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 20, text = "Kisa mwen menm David, mwen ka di ou, Seyè, apre sa? Ou konnen ki moun mwen ye, mwen menm k'ap sèvi ou la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 21, text = "Se paske ou te fè pwomès la, se paske ou te vle l' konsa, kifè ou te fè tout bèl bagay sa yo pou ou te fè m' konnen yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 22, text = "Seyè, Bondye mwen, ala gwo pouvwa ou la gwo! Pa gen tankou ou! Pa gen lòt Bondye pase ou menm! Yo te toujou di nou sa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 23, text = "Pa gen lòt nasyon sou latè tankou pèp Izrayèl la! Se ou menm ki delivre yo pou yo te ka tounen yon pèp ki rele ou pa ou. Se pou yo ase ou fè sa. Toupatou sou latè, y'ap nonmen non ou yo pou gwo mirak ak bèl bagay ou fè pou yo. Ou mete lòt nasyon deyò nan peyi ou la ansanm ak bondye yo pou fè plas pou pèp ou, pèp ou te delivre anba pouvwa pèp peyi Lejip la, pou yo te ka tounen pèp pa ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 24, text = "Ou fè pèp Izrayèl la tounen pèp pa ou pou tout tan, ou menm ou tounen Bondye yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 25, text = "Koulye a, Seyè, Bondye, se pou ou kenbe pwomès ou te fè sèvitè ou la ansanm ak fanmi li an. Se pou ou fè sa ou di w'ap fè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 26, text = "Toupatou sou latè y'a toujou rekonnèt jan ou gen pouvwa. y'a di se Seyè ki gen tout pouvwa a ki Bondye pèp Izrayèl la. Konsa, gouvènman ki nan men fanmi David, sèvitè ou la, va kanpe fèm pou tout tan anba pwoteksyon ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 27, text = "Seyè ki gen tout pouvwa a, Bondye pèp Izrayèl la, se ou menm ki te fè m' konnen tou sa. Ou te di m', mwen menm sèvitè ou la, w'ap ban mwen yon fanmi, lèfini w'ap fè baton gouvènman an toujou rete nan men fanmi mwen. Se poutèt sa mwen gen kouraj fè lapriyè sa a nan pye ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 28, text = "Koulye a, Seyè sèl Mèt, se ou ki Bondye tout bon an. Ou toujou kenbe pwomès ou yo. Gade bèl pawòl kè kontan ou di sèvitè ou la!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 7, verseNumber = 29, text = "Tanpri, beni tout fanmi mwen apre mwen pou yo ka toujou anba pwoteksyon ou. Wi, Seyè sèl Mèt, ou te pwomèt mwen sa. Se pou ou toujou voye benediksyon ou sou fanmi mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 1, text = "Apre sa, David atake moun Filisti yo ankò. Li bat yo byen bat. Se konsa li kraze pouvwa yo te gen nan peyi a, li pran peyi a nan men yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 2, text = "Lèfini li bat moun peyi Moab yo. Li fè prizonye yo kouche plat atè. Pou chak twa ladan yo, li touye de, li kite yonn vivan. Depi lè sa a moun peyi Moab yo soumèt devan David nèt. Li fè yo peye taks ba li chak lè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 3, text = "Apre sa, li bat Adadezè, pitit gason Reyòb, wa peyi Zoba a, ki t'ap mache pran zòn ki sou anwo larivyè Lefrat la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 4, text = "David pran mil sètsan (1700) kavalye nan lame wa Adadezè a, li fè yo prizonye ansanm ak venmil (20.000) sòlda ki t'ap mache apye. Lè li fin wete kont chwal pou san cha lagè, li fè koupe jarèt tout rès chwal yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 5, text = "Moun peyi Siri ki te rete lavil Damas yo voye yon lame pou pote Adadezè, wa peyi Zoba a, konkou. David atake yo, li bat yo tou. Li touye venndemil (22.000) sòlda.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 6, text = "Apre sa, David mete kèk ganizon sòlda pa l' nan teritwa Damas la. Moun peyi Siri yo soumèt devan li. Li fè yo peye l' taks chak lè. Se konsa, Seyè a te fè David genyen tout batay kote l' pase.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 7, text = "David sezi tout gwo plak pwotèj an fè chèf lame wa Adadezè yo, li pote yo lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 8, text = "Li pran yon gwo kantite kwiv li te jwenn lavil Beta ak lavil Bewotayi, ki te pou Adadezè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 9, text = "Lè Tòy, wa lavil Amat la, tande jan David te kraze tout lame Adadezè a,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 10, text = "li voye pitit li, Joram, al wè David pou di l' bonjou epi pou fè l' konpliman dèske li te bat Adadezè, paske Tòy te toutan ap fè lagè ak Adadezè. Joram te pote kado fèt an lò, an ajan ak an kwiv bay David.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 11, text = "Wa David pran tout bagay sa yo, li mete yo apa pou sèvis Seyè a ansanm ak tout lò ak ajan li te pran lakay moun lòt nasyon li te fè soumèt devan li,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 12, text = "ki vle di moun peyi Edon, moun peyi Moab, moun peyi Amon, moun peyi Filisti ak moun peyi Amalèk. Li fè menm bagay la tou ak tou sa li te pran apre lagè ak Adadezè, pitit Reyòb, wa Zoba a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 13, text = "Non David te nan bouch tout moun pi rèd toujou, lè li te fin touye dizwitmil (18.000) moun peyi Edon nan fon Sèl la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 14, text = "Li mete kèk ganizon sòlda pa l' nan teritwa Edon an. Moun Edon yo soumèt devan li. Li fè yo peye l' taks chak lè. Se konsa Seyè a te fè David genyen tout batay kote l' pase.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 15, text = "David t'ap gouvènen tout pèp Izrayèl la. Li te fè tout moun jistis san patipri. Li te fè tout zafè l' dwat.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 16, text = "Joab, pitit gason Sewouya a, te kòmandan lame a. Jozafa, pitit gason Akiloud la, te reskonsab achiv yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 17, text = "Zadòk, pitit gason Akitoub la, ak Akimelèk, pitit gason Abyata a, te prèt. Seraja te sekretè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 8, verseNumber = 18, text = "Benaja, pitit gason Jeojada a, te chèf keretyen ak peletyen yo ki te gad pèsonèl wa a. Pitit gason David yo menm te prèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 1, text = "Yon jou, David mande: -Pa rete yon moun menm nan fanmi Sayil la? Si genyen, mwen ta renmen aji byen avè l' poutèt Jonatan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 2, text = "Te gen yon domestik ki t'ap travay lakay Sayil ki te rele Ziba. Yo fè chache l', yo mennen l' bay wa a. Wa a mande l': -Se ou menm nonm yo rele Ziba a? Li reponn: -Wi, monwa. Mwen la pou m' sèvi ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 3, text = "Wa a mande l': -Pa gen yon moun ki rete nan fanmi Sayil la, pou m' ka fè kichòy pou li jan mwen te pwomèt sa devan Bondye? Ziba reponn li: -Wi, gen yonn nan pitit gason Jonatan yo ki vivan toujou. Men, li enfim nan tou de pye l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 4, text = "Wa a mande l': -Kote l' ye? Ziba reponn: -Li kay Maki, pitit gason Amiyèl la, lavil Lodeba.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 5, text = "Se konsa, David voye chache l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 6, text = "Lè Mefibochèt, pitit Jonatan, pitit pitit Sayil la, rive, li mete ajenou, li bese tèt li rive atè devan David. David di l' konsa: -Mefibochèt? Li reponn: -Se mwen menm, monwa. M' la pou m' sèvi ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 7, text = "David di l' konsa: -Ou pa bezwen pè. Mwen pral aji byen avè ou poutèt Jonatan, papa ou. M'ap renmèt ou tout tè ki te pou Sayil, granpapa ou. Lèfini, chak jou w'a vin manje sou tab avè m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 8, text = "Mefibochèt bese tèt li byen ba ankò, li di: -Monwa, poukisa w'ap okipe yon vye chen tou mouri tankou mwen?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 9, text = "Lè sa a, wa a rele Ziba, domestik Sayil la, li di l' konsa: -Mwen renmèt Mefibochèt, pitit pitit gason mèt ou a, tou sa ki te pou Sayil ak fanmi l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 10, text = "Ou men, ansanm ak pitit gason ou yo ak moun k'ap sèvi avè ou yo, nou pral travay tè a pou li. W'a pote rekòt la ba li pou rès fanmi l' ka jwenn manje pou yo manje. Men, Mefibochèt li menm ap toujou vin manje chak jou sou tab avè m'. Ziba te gen kenz pitit gason ak ven moun k'ap sèvi l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 11, text = "Ziba reponn li: -M'ap fè tou sa monwa ban m' lòd fè. Se konsa, Mefibochèt toujou manje sou tab ansanm ak David tankou si li te yonn nan pitit wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 12, text = "Mefibochèt te gen yon pitit gason ki te piti joujou. Li te rele Mika. Tout moun ki te rete kay Ziba t'ap travay pou Mefibochèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 9, verseNumber = 13, text = "Se konsa, Mefibochèt ki te enfim nan tou de pye l' yo rete lavil Jerizalèm. Li t'ap manje chak jou sou tab ansanm ak wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 1, text = "Kèk tan apre sa, Nakach, wa lavil Amon an, mouri. Se pitit li, Anoun, ki moute wa nan plas li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 2, text = "David di: -Se pou m' aji byen ak Anoun menm jan papa l', Nakach, te aji byen avè m'. Se konsa David voye mesaje al di Anoun jan sa te fè l' lapenn lè l' pran nouvèl lanmò papa l'. Lè mesaje yo rive lavil Amon,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 3, text = "chèf moun Amon yo di wa Anoun konsa: -Pa konprann se sèlman pou lanmò papa ou la kifè David voye mesaje sa yo bò kote ou pou konsole ou. Detwonpe ou. Li voye yo isit la pou yo wè jan lavil la ye, pou yo gade byen jan sa ap pase nan lavil la. Konsa, pita li ka vin pran lavil la nan men nou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 4, text = "Sa Anoun fè lè sa a, li pran moun David te voye yo, li raze tout yon bò nan bab yo, li koupe anba rad yo ra dèyè yo, li voye yo tounen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 5, text = "Mesye yo te wont anpil pou yo te tounen lakay yo konsa. Lè David vin konn sa ki te rive yo, li voye di yo rete lavil Jeriko, y'a tounen lakay yo lè bab yo va pouse ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 6, text = "Moun Amon yo vin konprann yo te fè David fache. Yo voye chache venmil (20.000) sòlda lavil Bètreyòb ak lavil Zoba nan peyi Aram lan, ak douzmil (12.000) gason lavil Tòb. Yo voye chache wa lavil Maka a tou ansanm ak mil (1.000) sòlda. Yo peye yo pou yo vin goumen pou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 7, text = "David menm vin konn sa, li voye Joab ak tout lame vanyan sòlda li yo al kontre yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 8, text = "Moun Amon yo soti, y' al pran pozisyon devan pòtay lavil Raba, kapital yo a. Moun Aram ki soti lavil Bètreyòb ak lavil Zoba yo ansanm ak mesye lavil Tòb yo ak mesye lavil Maka yo pran pozisyon nan plenn lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 9, text = "Joab te wè lame lènmi yo te ka atake l' ni sou devan ni sou dèyè. Sa l' fè? Li chwazi pi bon sòlda nan lame pèp Izrayèl la, li mete yo an pozisyon devan lame moun Aram yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 10, text = "Lèfini, li mete Abichayi, frè l' la, alatèt rès lame a, li fè yo pran pozisyon devan moun Amon yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 11, text = "Joab di Abichayi konsa: -Si ou wè moun Aram yo soti pou yo bat mwen, w'a vin ede m'. Konsa tou, si mwen wè moun Amon yo vle pi fò pase ou, m'a vin ede ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 12, text = "Mete gason sou nou. Kouraj! Nou pral goumen rèd mare pou pèp nou an ak pou lavil Bondye nou an. Bondye va fè sa li vle li menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 13, text = "Joab ak sòlda li yo mache sou moun Aram yo. Moun Aram yo kouri pou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 14, text = "Lè moun Amon yo wè moun Aram yo kouri ale, yo kouri tou pou Abichayi, yo antre nan lavil la. Lè sa a, Joab sispann batay la ak moun Amon yo, li tounen lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 15, text = "Lè moun Aram yo wè moun Izrayèl yo te bat yo ankò, yo sanble dènye sòlda yo te genyen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 16, text = "Adadezè voye yon mesaj bay moun Aram ki rete lòt bò larivyè Lefrat la, pou yo pare vin goumen pou li. Yo reyini lavil Elam. Se Chobak, chèf lame Adadezè a, ki te alatèt yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 17, text = "Lè David vin konn sa, li sanble tout lame pèp Izrayèl la, li janbe lòt bò larivyè Jouden, li rive Elam. Moun Aram yo pran pozisyon devan li. Epi batay la konmanse.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 18, text = "Moun Izrayèl yo fè moun Aram yo kouri met deyò. David ak sòlda li yo touye sètsan (700) sòlda ki te sou cha lagè, katòzmil (14.000) sòlda ki te sou chwal. Yo blese Chobak, chèf lame lènmi yo, ki mouri la menm kote yo t'ap goumen an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 10, verseNumber = 19, text = "Lè tout ti wa ki te mete tèt ansanm ak Adadezè yo wè jan moun Izrayèl yo te bat yo, yo fè lapè ak yo, yo soumèt devan yo. Se konsa, moun Aram pa pran chans al pote moun Amon yo sekou ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 1, text = "Nan prentan apre sa, nan epòk wa yo konn soti pou al fè lagè, David voye Joab ansanm ak tout lòt ofisye yo alatèt lame pèp Izrayèl la al goumen ak moun Amon yo. Yo ravaje peyi Amon an, yo sènen lavil Raba. David menm te rete lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 2, text = "Yon jou, bò aswè, David te fin fè yon ti poze, li leve, li soti al sou teras ki anwo palè a. Antan li la, li wè yon fanm ki t'ap benyen. Fanm lan te bèl anpil.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 3, text = "Li voye chache konnen ki moun fanm lan te ye. Yo vin di l' se Batcheba, pitit fi Eliyam lan, madan Ouri, moun peyi Et la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 4, text = "David voye mesaje al chache l' mennen l' ba li, li kouche avè l'. Lè sa a Batcheba te fèk fin fè sèvis pou l' fè apre règ li. Apre sa, Batcheba tounen lakay li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 5, text = "Fanm lan vin ansent. Li voye nouvèl bay David pou fè l' konn sa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 6, text = "David voye yon mesaj bay Joab, li mande l' pou l' voye Ouri, moun peyi Et la, ba li. Se konsa, Joab voye Ouri bay David.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 7, text = "Lè Ouri rive, David mande l' nouvèl Joab ak sòlda yo, ki jan batay la ye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 8, text = "Apre sa, li di Ouri: -Desann al lakay ou non! Al poze kò ou! Ouri soti. David voye yon kado pou li lakay li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 9, text = "Men Ouri pa al lakay li. Li kouche bò pòtay palè a ansanm ak tout lòt sòlda wa yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 10, text = "Lè David vin konnen Ouri pa t' al lakay li, li mande l': -Ou fèk antre soti nan vwayaj, poukisa ou pa al lakay ou?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 11, text = "Ouri reponn David: -Sòlda Izrayèl yo ak sòlda Jida yo byen lwen ap fè lagè, Bwat Kontra Seyè a ansanm ak yo. Kòmandan Joab ak lòt chèf lame monwa yo ap pase nwit deyò nan plenn yo. Ki jan ou vle pou m' al lakay mwen, manje, bwè, kouche ak madanm mwen? Mwen fè sèman sou tèt ou, menm jan ou vivan an, m' pa ka janm fè bagay konsa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 12, text = "David di li: -Bon. Ou mèt rete pase rès jounen an isit la. Denmen m'a voye ou ale. Se konsa, Ouri rete lavil Jerizalèm pou de jou ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 13, text = "David envite l' vin manje avè l'. Li fè l' bwè jouk li sou. Men jou swa sa a tou, Ouri pa desann al lakay li. Li kouche sou kabann li ansanm ak sòlda palè wa yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 14, text = "Nan denmen, David ekri Joab yon lèt, li bay Ouri pote l' ale.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 15, text = "Nan lèt la, li te ekri: W'a mete Ouri devan nèt, kote batay la pi cho a. Apre sa, rale kò ou dèyè, kite yo touye l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 16, text = "Se konsa, Joab ki te sènen lavil Raba a voye Ouri kote li te konnen lènmi yo te pi fò a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 17, text = "Lame lènmi yo soti nan lavil la, yo vin kontre ak lame Joab la. Gen anpil sòlda ak anpil ofisye lame David la ki te mouri. Ouri, moun peyi Et la, mouri tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 18, text = "Joab voye rakonte David tout ti detay sou jan batay la pase.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 19, text = "Epi li bay mesaje a lòd sa a: -Lè w'a fin rakonte wa a tout ti detay batay la,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 20, text = "li ka fè kòlè, li ka di ou: Poukisa nou te pwoche pre lavil la konsa pou m' te goumen ak lènmi yo? Se konnen nou pa konnen yo te ka rete sou tèt miray la pou yo tire flèch sou nou?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 21, text = "Nou gen lè bliye jan Abimelèk, pitit Jedeyon an te mouri lavil Tebès? Se yon fanm ki te rete sou tèt miray la, li voye yo wòl moulen sou li, li touye l' frèt. Poukisa atò nou te pwoche pre lavil la konsa? Si wa a pale konsa avè ou, w'a di l': Ouri, moun peyi Et la, ofisye lame ou la, mouri tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 22, text = "Mesaje a ale, li rakonte David tou sa Joab te ba li lòd rakonte l' la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 23, text = "Li di l': -Lènmi nou yo te pi fò pase nou. Yo fè yon soti nan lavil la, yo vin goumen avè nou nan plenn lan. Men nou fè yo kase tèt tounen, nou kouri dèyè yo jouk devan pòtay lavil la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 24, text = "Se lè sa a, yo rete sou tèt miray yo, yo voye flèch sou nou. Gen kèk ofisye lame wa a ki mouri. Ouri, moun peyi Et la, ofisye wa a, mouri tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 25, text = "David di mesaje a: -Ankouraje Joab. Di li li pa bezwen kite sa fatige l' twòp. Se toujou konsa lè y'ap fè lagè. Ou pa janm konnen kilès ki pral mouri. Di li pare pou li fè yon gwo atak sou lavil la pou li pran l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 26, text = "Lè Batcheba vin pran nouvèl mari l' te mouri, li pran lapenn pou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 11, verseNumber = 27, text = "Lè seremoni lantèman yo fini, David voye chache l', li pran l' lakay li. Batcheba vin madanm li. Li fè yon pitit gason pou David. Men, sa David te fè a pa t' fè Seyè a plezi menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 1, text = "Seyè a voye pwofèt Natan kot David. Natan rive kote l', li di l' konsa: -Vwala te gen de nonm ki t'ap viv nan yon lavil. Yonn te rich, lòt la te pòv.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 2, text = "Nonm rich la te gen mouton ak bèf an kantite.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 3, text = "Pòv la menm pa t' gen pase yon sèl ti mouton li te achte. Li swen li. Se anndan lakay li ansanm ak pitit li yo ti mouton an grandi. Se nan asyèt malere a menm ti mouton an te konn manje. Se nan gode l' li bwè dlo. Se sou janm li li konn dòmi. Ti mouton an te tankou yon pitit fi pou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 4, text = "Yon jou, yon vizitè vin rive lakay nonm rich la. Nonm rich la pa t' santi kouraj li pou l' te pran yonn nan mouton l' yo osinon nan bèf li yo pou l' fè manje bay vizitè a. Li pran ti mouton malere a, li fe manje ak li bay vizitè ki te lakay li a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 5, text = "David fache anpil sou nonm rich la. Li di Natan konsa: -Mwen fè sèman nan non Seyè ki vivan an! Nonm ki fè bagay sa a merite pou yo touye l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 6, text = "Pou l' peye bagay lèd li fè a, l'ap renmèt kat fwa lavalè sa l' te pran an, paske li san pitye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 7, text = "Le sa a, Natan di David: -Nonm sa a, se ou menm! Men mesaj Seyè a, Bondye pèp Izrayèl la, voye ba ou: Mwen te fè ou wa pèp Izrayèl la. Mwen sove ou anba men Sayil.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 8, text = "Mwen ba ou baton kòmandman ki te nan men l' lan ansanm ak tout madanm li yo. Mwen mete ou wa pou gouvènen ni moun Izrayèl yo, ni moun Jida yo. Si sa pa t' kont toujou, mwen ta ba ou menm de fwa lavalè ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 9, text = "Poukisa atò ou pa swiv lòd mwen yo? Poukisa ou fè mechanste sa a? Ou fè yo touye Ouri nan lagè, ou kite moun Amon yo touye l'. Lèfini, ou pran madanm li!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 10, text = "Koulye a, paske ou pa t' koute m', paske ou pran madan Ouri, moun Et la, pou madanm ou, nan fanmi ou ap toujou gen goumen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 11, text = "Men sa mwen menm Seyè a, mwen di: M'ap fè yon moun nan fanmi ou menm soti pou ba ou traka. M'ap wete madanm ou yo nan men ou, m'ap bay yon moun nan fanmi ou yo. L'a kouche avèk yo devan tout moun.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 12, text = "Ou menm, ou te fè zafè ou la an kachèt. Mwen menm, m'ap fè sa rive devan tout moun pou tout pèp Izrayèl la ka wè sa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 13, text = "David di Natan konsa: -Wi, mwen rekonèt mwen peche kont Seyè a! Lè sa a Natan di l' konsa: -Bondye sèl Mèt la p'ap pini ou pou sa ou fè a, ou p'ap mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 14, text = "Sèlman, ak sa ou fè la a, ou moutre jan ou ka derespekte Seyè a. Se poutèt sa pitit ou fèk genyen an ap mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 15, text = "Apre sa, Natan al lakay li. Seyè a fè pitit madan Ouri te fè pou David la vin malad grav.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 16, text = "David tonbe lapriyè Seyè a pou ti gason an. Li derefize mete anyen nan bouch li. Chak swa, li antre nan chanm li, li pase nwit lan kouche atè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 17, text = "Chèf ki te reskonsab palè li a al jwenn li, yo fè sa yo kapab pou fè l' leve atè a, men li derefize. Konsa tou, li pa t' vle manje avèk yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 18, text = "Apre yon senmenn, pitit la mouri. Chèf kay David yo te pè al ba li nouvèl la. Yo t'ap di: Si lè pitit la te malad ase, David te refize reponn nou lè nou pale avè l', ki jan pou n' al di l' koulye a pitit la mouri? Li ka fè malè sou tèt li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 19, text = "Men David wè moun li yo t'ap pale nan zòrèy yonn ak lòt, li vin konprann pitit la mouri. Li mande yo: -Pitit la mouri? Yo reponn li: -Wi, li mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 20, text = "David leve atè a, li al benyen, li penyen tèt li, li chanje rad sou li. li ale nan kay Seyè a, li lapriyè. Apre sa, li tounen lakay li, li mande pou yo sèvi l' manje. Li manje.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 21, text = "Moun pa l' yo t'ap di l': -Monwa, nou pa konprann sa w'ap fè konsa? Lè pitit la te vivan, ou t'ap plede kriye, ou rete san manje. Men, mouri pitit lan mouri, ou leve, ou manje.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 22, text = "David reponn yo: -Wi, mwen t'ap kriye, mwen te rete san manje lè pitit la te vivan toujou. Mwen te kwè Seyè a ta gen pitye pou mwen, li pa ta kite pitit la mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 23, text = "Men, koulye a, pitit la mouri, sa m' bezwen rete san manje toujou fè? Eske mwen ka fè l' leve ankò? Yon jou se mwen ki gen pou ale kote l' ye a. Men li menm, li p'ap janm ka tounen vin jwenn mwen ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 24, text = "Apre sa, David al konsole Batcheba, madanm li. Li kouche avè l', Batcheba vin ansent, li fè yon pitit gason. David rele l' Salomon. Seyè a te renmen ti gason sa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 25, text = "Li bay pwofèt Natan lòd al di David rele pitit la Jedidya, paske Seyè a te renmen l' vre.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 26, text = "Pandan tout tan sa a, Joab t'ap goumen toujou devan lavil Raba, kapital peyi Amon an. Li te prèt pou pran katye kote wa a te rete a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 27, text = "Li voye mesaje al di David pou li: -Mwen atake lavil Raba. Mwen pran rezèvwa dlo yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 28, text = "Koulye a, sanble tout rès lame a, mache sou lavil la, vin pran li. Mwen pa ta vle se mwen menm ki pran lavil la lèfini pou tout lwanj lan vin pou mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 29, text = "Se konsa, David sanble tout lame a, li mache sou lavil Raba. Li atake l', li pran l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 30, text = "Estati Milkòm, zidòl moun Amon yo, te gen yon gwo kouwòn fèt an lò sou tèt li. Kouwòn lan te peze swasannkenz liv, li te gen yon gwo pyè koute chè ladan l'. David pran kouwòn lò ki te sou tèt zidòl la, li mete l' sou tèt pa l'. Lèfini, se pa de bagay li pa pran nan lavil la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 12, verseNumber = 31, text = "Li pran moun ki te rete nan lavil la, li fè yo travay ak goyin, wou ak rach. Li mete yo travay ap fè brik. Li fè menm bagay la tou nan tout lòt lavil nan peyi Amon an. Apre sa, li tounen Jerizalèm ak tout moun li yo.", bookId = 10)
    )

    private val part2 = listOf(
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 1, text = "Men sa ki vin rive apre sa: Absalon, pitit gason David la, te gen yon sè ki te bèl anpil. Li te rele Tama. Amnon, yon lòt pitit gason David, tonbe damou pou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 2, text = "Amnon te sitèlman renmen l', li vin malad paske li pa t' ka fè anyen pou sa. Tama te tifi toujou. Yo pa t' kite l' kontre ak ankenn gason.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 3, text = "Men, Amnon te gen yon zanmi, yon moun yo te rele Jonadab, pitit gason Chimeya, frè David. Jonadab sa a te mètdam anpil.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 4, text = "Li di Amnon konsa: -Ou se pitit wa a. Chak jou mwen wè figi ou kagou. Sa ki genyen? Amnon reponn li: -Mwen renmen Tama, sè Absalon, frè menm papa avè m' lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 5, text = "Jonadab di li: -Pran pòz malad ou, moute kabann ou kouche. Lè papa ou va vin wè ou, w'a di l': Tanpri, kite Tama, sè m' lan, vin ban m' manje. Mwen ta renmen pou li pare manje a devan m' pou m' wè l', lèfini pou l' sèvi m' manje a li menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 6, text = "Se konsa Amnon moute kabann li kouche, li pran pòz malad li. Wa David vin wè l'. Amnon di l' konsa: -Tanpri, kite Tama vin pare de ti gato la devan m' lan, lèfini pou l' sèvi m' yo li menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 7, text = "David voye komisyon bay Tama nan palè a pou l' ale kay Amnon pare manje pou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 8, text = "Tama ale vre kay Amnon, li jwenn li kouche sou kabann li. Li pran ti gout farin frans, li pare l', li fè kèk gato pou li devan je l'. Lèfini, li mete yo kwit.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 9, text = "Apre sa, li wete yo nan pwelon an devan Amnon. Men, Amnon refize manje. Li di l': -Fè tout moun soti! Lè tout moun fin soti,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 10, text = "Amnon di Tama konsa: -Pote gato yo nan chanm lan. Se ou menm ki pou sèvi m'. Tama pran gato li te fè yo, li pote yo bay Amnon nan chanm lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 11, text = "Antan l'ap lonje gato a ba li, Amnon mete men sou li. Li di l' konsa: -vin kouche avè m' non, sè m'!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 12, text = "Tama di l': -Non, frè m'! Pa fòse m'! Sa pa fèt konsa nan peyi Izrayèl! Pa fè bagay lèd sa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 13, text = "Apre sa, mwen p'ap ka gade moun nan je ankò. Ou menm, pou tèt pa ou, w'ap pase pou yonn nan pi move moun nan peyi Izrayèl. Tanpri, pale ak wa a. Mwen sèten li p'ap refize ou marye avè m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 14, text = "Men, Amnon pa wè li pa tande, li kenbe l' la. Li te gen plis fòs pase l', li kouche ak li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 15, text = "Lèfini, li santi li rayi Tama pou l' mouri. Li vin rayi l' plis pase jan li te renmen l' lan. Li di l': -Mete ou deyò lakay mwen!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 16, text = "Tama reponn li: -A non! Mete m' deyò konsa! Sa pi mal ankò pase sa ou sot fè m' la a! Men Amnon pa t' soti pou koute l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 17, text = "Li rele gason ki t'ap sèvi l' la, li di l': -Wete fi sa a devan je m'! Mete l' deyò. Lèfini, fèmen pòt la akle dèyè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 18, text = "Gason an fè Tama soti deyò, li fèmen pòt la akle dèyè l'. Tama te gen yon rad long ak gwo manch sou li. Se rad konsa pitit wa yo te konn mete sou yo lè yo poko marye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 19, text = "Li simen sann dife sou tèt li, li chire rad ki te sou li a, li mete de men nan tèt, li pran rele epi li ale.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 20, text = "Lè sa a, Absalon, frè l' la, mande l': -Eske Amnon, frè ou la, fè kadejak sou ou? Tanpri, sè m' pa kite sa fatige ou twòp, tande. Se frè ou li ye. Pa di pesonn anyen. Se konsa Tama rete pou kont li kay Absalon, frè l' la. Li te nan gwo lapenn.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 21, text = "Lè wa David vin konn sa ki te pase, li te move. Men, li pa di Amnon anyen, paske se te premye pitit gason l'. Li te renmen l' kou de grenn je nan tèt li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 22, text = "Absalon vin rayi Amnon pou kadejak li te fè sou Tama, sè li a. Li koupe l' bonjou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 23, text = "Dezan apre sa, Absalon t'ap koupe lenn mouton l' yo lavil Baal azò, toupre lavil Efrayim. Li envite tout pitit gason wa yo vin manje.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 24, text = "li al jwenn wa David, li di l' konsa: -Monwa, mwen pral koupe lenn mouton m' yo. Ou pa ta vle vini ansanm ak tout chèf ou yo lakay mwen?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 25, text = "W'a reponn li: -Non, pitit mwen! Se pral twòp traka pou ou si nou tout nou vini. Absalon pèsiste, men wa a pa pran priyè, li voye l' ale ak benediksyon l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 26, text = "Lè sa a Absalon di l': -Men, èske w'ap kite Amnon, frè m' lan, vini ak nou? Wa a reponn li? -Poukisa pou l' ale a?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 27, text = "Men Absalon sitèlman pèsiste, bout pou bout, David kite Amnon ale ansanm ak tout lòt pitit gason l' yo. Absalon te pare yon gwo fèt tankou si l' t'ap fè l' pou yon wa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 28, text = "Epi li bay domestik li yo lòd sa a, li di yo: -Gade byen, lè n'a wè Anmon ak bon gwòg nan tèt li, m'a di nou: Desann Amnon. n'a touye l'. Nou pa bezwen pè, mwen pran tout reskonsablite a sou mwen. Mete gason sou nou. Frape san tranble.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 29, text = "Se konsa domestik Absalon yo swiv lòd Absalon te ba yo, yo touye Amnon. Lè sa a, tout lòt pitit gason David yo leve, yo moute milèt yo, yo met deyò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 30, text = "Yo te sou chemen lakay yo toujou, lè David vin pran nouvèl Absalon touye dènye pitit gason li yo, pa gen yonn ki chape.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 31, text = "Wa a leve kanpe, li chire rad ki te sou li, li lage kò l' atè. Tout moun ki te avèk wa a chire rad sou yo tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 32, text = "Men Jonabad, pitit gason Chimeya, frè David la, di l': -Monwa, yo pa touye tout pitit gason ou yo non. Se Amnon ase ki mouri, paske Absalon te gen lide nan tèt li pou l' te fè sa depi lè Amnon te fè kadejak sou Tama, sè l' la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 33, text = "Koulye a, monwa, ou pa bezwen koute moun k'ap vin di ou tout pitit gason ou yo mouri. Se Amnon ase yo touye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 34, text = "Lè sa a Absalon te gen tan kraze rak. Sòlda ki te faksyonnè a wè yon foul moun ki t'ap kouri desann ti pant sou chemen lavil Owonayim lan. li al jwenn wa a, li di l' sa li wè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 35, text = "Jonabad di wa a konsa: -Men sa m' t'ap di ou la. Se pitit gason ou yo k'ap vini.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 36, text = "Fini li fin di sa, pitit gason David yo rive. Yo pete rele. Wa a pran rele ansanm ak tout chèf li yo. Yo rele kont rele yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 37, text = "Absalon menm kraze rak, li al kay Talmayi, pitit gason Amiyoud la, ki te wa lavil Gechou a. David menm te nan gwo lapenn pandan kèk jou pou lanmò Amnon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 38, text = "Absalon rete pase twazan lavil Gechou kote li te kouri al kache a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 13, verseNumber = 39, text = "Lè wa David fin konsole apre lanmò Amnon, li vin anvi wè Absalon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 1, text = "Joab, pitit Sewouya a, te konnen wa David te anvi wè Absalon anpil.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 2, text = "Sa li fè, li voye lavil Tekoa al chache yon fanm ki te gen anpil ladrès. Lè fanm lan rive, li di l' konsa: -Ou pral pran pòz ou nan gwo lapenn. W'ap mete rad dèy sou ou, lèfini pa mete ankenn odè sou ou. Se pou yo ka pran ou pou yon moun ki gen yon moun mouri depi lontan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 3, text = "Lèfini, ou pral bò kote wa a, w'a di l' tou sa m'a di ou di li. Apre sa, Joab fè bouch li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 4, text = "Fanm lan ale vre bò kot wa a, li tonbe ajenou devan wa a, li bese tèt li jouk atè, epi li di: -Tanpri, monwa, fe kichòy pou mwen!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 5, text = "Wa a mande l': -Kisa ou genyen? Fanm lan reponn li: -Adje, monwa! Se yon pòv vèv mwen ye. Mari m' mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 6, text = "Li kite m' ak de pitit gason. Yon jou, yo te nan jaden, yonn gen kont ak lòt, yo goumen. Pa t' gen pesonn la pou separe yo. Yonn ladan yo touye lòt la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 7, text = "Koulye a menm, tout fanmi m' yo leve dèyè m', y'ap mande m' pou m' lage sa ki te touye lòt la nan men yo pou yo touye l' tou, paske li te touye frè l' la. Si yo fè sa, m'ap rete san pitit gason. Y'ap wete dènye ti espwa ki te rete m' lan. Lèfini, mari m' p'ap gen yon pitit gason pou leve non l' sou tè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 8, text = "Wa a di madanm lan: -Ou mèt al lakay ou. M'ap okipe sa pou ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 9, text = "Fanm lavil Tekoa a di wa a konsa: -Monwa, nenpòt kisa w'a deside fè, si pou gen repwòch, y'a repwoche mwen menm ansanm ak fanmi pa m'. Men, ou menm ak gouvènman ou, nou pa reskonsab anyen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 10, text = "Wa a reponn li: -Si yon moun konprann pou li kraponnen ou, mennen l' ban mwen. Li p'ap janm chache ou kont ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 11, text = "Fanm lan di ankò: -Tanpri, monwa! Lapriyè Seyè a, Bondye ou la, pou moun nan fanmi an ki reskonsab pou tire revanj lanmò pitit gason m' lan pa fè plis dega toujou, pou l' pa touye lòt pitit gason ki rete m' lan. David reponn li: -Mwen fè sèman nan non Seyè ki vivan an, mwen p'ap kite yo manyen yon grenn cheve nan tèt pitit gason ou lan!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 12, text = "Lè sa a, fanm lan di ankò: -Tanpri, monwa! Kite m' di ou yon dènye pawòl. Wa a reponn li: -Pale non.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 13, text = "Fanm lan di l' konsa: -Poukisa ou fè move lide sa a sou pèp Bondye a? Ou pa vle kite pwòp pitit gason ou lan tounen nan peyi a. Jan ou sot pale a, ou kondannen pwòp tèt ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 14, text = "Nou tout gen pou mouri. Nou tankou dlo. Depi ou lage dlo atè, ou pa ka ranmase l' ankò. Lè yon moun fin mouri, li mouri nèt. Men, Bondye ta vle pou moun ki te kouri al chache pwoteksyon nan peyi etranje a tounen nan peyi l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 15, text = "Monwa, rezon ki fè mwen te vin pale avè ou la, se paske moun yo t'ap fè m' pè. Mwen di nan kè m' mwen pral pale ak wa a. Wa a ka fè sa m'ap mande l' la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 16, text = "Mwen t'ap di wa a ka koute m', li ka delivre m' anba men moun ki soti pou yo touye pitit gason m' lan ansanm avè m', anba men moun ki soti pou wete moso tè ki vin pou nou nan peyi Bondye bay pèp li a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 17, text = "Mwen di ankò pawòl monwa va ban m' kouraj paske wa a se tankou yon zanj Bondye li ye. Li konn rekonèt sa ki byen ak sa ki mal. Mwen mande pou Seyè a, Bondye ou la, toujou kanpe la avè ou!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 18, text = "Wa a di l' konsa: -Mwen pral mande ou kichòy, pa kache m' anyen. Fanm lan reponn: -Monwa, mande m' sa ou vle?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 19, text = "Wa a mande l': -Eske Joab pa nan plan sa a avè ou? Fanm lan reponn li: -Menm jan ou vivan an, monwa, pa gen anyen ki pi sèten pase sa ou di la a. Wi, monwa. Se Joab, chèf lame ou la, ki di m' tou sa pou m' fè ak tou sa pou m' di.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 20, text = "Men, si li fè l' se paske li vle pou tout bagay sa a regle. Monwa, ou gen bon konprann tankou yon zanj Bondye, ou konnen tou sa ki ap pase nan peyi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 21, text = "Pita, wa a di Joab konsa: -Mwen pral fè sa ou vle m' fè a. Ale chache jennonm yo rele Absalon an, mennen l' tounen isit la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 22, text = "Joab tonbe ajenou devan David, li bese tèt li jouk atè. Li di: -Se pou Bondye beni ou, monwa! Jòdi a mwen konnen ou kontan avè m' vre, paske ou ban mwen sa m' mande ou la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 23, text = "Joab leve, li ale lavil Gechou, li mennen Absalon tounen lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 24, text = "Men, wa a bay lòd pou Absalon pa vin rete nan palè a, paske li pa vle pou l' parèt devan li. Se konsa Absalon al rete lakay li, li pa janm parèt devan wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 25, text = "Pa t' gen pi bèl gason nan tout peyi Izrayèl la pase Absalon. Tout moun t'ap di sa. Pran depi nan cheve l' rive nan pwent zòtèy li, li pa t' gen ankenn defo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 26, text = "Li te gen anpil cheve. Li te blije koupe yo chak lanne paske, lè yo te lonje yo te vin twò lou pou li. Lè yo peze cheve yo, yo ka rive peze senk liv dapre sistèm pèz yo sèvi kay wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 27, text = "Absalon te gen twa pitit gason ak yon pitit fi ki te rele Tama. Tama te bèl anpil.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 28, text = "Absalon pase dezan lavil Jerizalèm san li pa janm parèt devan wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 29, text = "Apre sa, li voye chache Joab pou mande l' al kote wa a pou li. Men, Joab pa vini. Yon lòt fwa ankò, Absalon voye chache l'. Fwa sa a tou Joab refize vini.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 30, text = "Lè sa a, Absalon di domestik li yo: -Gade! Nou wè jaden Joab ki toupre jaden pa m' lan. Li plante lòj. Enben, al met dife ladan l'. Y' ale, yo mete dife nan jaden Joab la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 31, text = "Joab al lakay Absalon, li mande l': -Poukisa moun pa ou yo mete dife nan jaden m' lan?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 32, text = "Absalon reponn li: -Paske ou pa t' vle vini lè mwen te voye chache ou la. Mwen te bezwen ou ale bò kote wa a pou mwen pou ou mande l' sa m' te bezwen kite lavil Gechou a vin isit la fè. Pito m' te rete laba a. Koulye a, mwen ta renmen ou jwenn yon jan pou m' parèt devan wa a. Si m' antò, li mèt touye m'!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 14, verseNumber = 33, text = "Se konsa Joab al bò kote wa David, li rapòte l' sa Absalon te di l' la. Wa a voye chache Absalon. Absalon vini, li tonbe ajenou devan wa a, li bese tèt li jouk atè. Wa resevwa l', li bo l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 1, text = "Apre sa, Absalon achte yon cha lagè ak tout chwal pou tèt pa li. Li pran senkant gason pou mache avèk li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 2, text = "Chak maten, Absalon leve byen bonè, li al kanpe sou wout la bò pòtay lavil la. Chak fwa yon moun vini ak yon pwoblèm li ta renmen wa a regle pou li, Absalon rele l' sou kote, li mande l' ki bò li moun. Apre moun lan fin di l' moun ki branch fanmi li ye,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 3, text = "Absalon di l' konsa: -Gade! Se ou menm ki gen rezon, lalwa avè ou. Men, p'ap gen yon moun kay wa a k'ap koute ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 4, text = "Apre sa, li di ankò: -Ki moun ki va mete m' chèf nan peyi Izrayèl la? Lè sa a, tout moun ki ta gen yon zafè osinon yon plent ta vin jwenn mwen, mwen ta fè l' jistis.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 5, text = "Chak fwa yon moun pwoche bò Absalon pou mete ajenou devan l', Absalon lonje men l', li kenbe l' epi li bo l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 6, text = "Se konsa Absalon te fè ak tout moun peyi Izrayèl ki te vin bò kote wa a pou chache jistis. Se konsa li fè yo vin renmen l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 7, text = "Apre katran, Absalon di wa David konsa: -Monwa, tanpri! Kite m' ale lavil Ebwon pou m' ka kenbe yon pwomès mwen te fè Seyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 8, text = "Antan mwen te lavil Gechou nan peyi Siri, mwen te pwomèt Seyè a si m' te tounen lavil Jerizalèm, mwen ta fè yon sèvis pou li Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 9, text = "Wa a di l': -Ale ak kè poze. Se konsa Absalon ale lavil Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 10, text = "Menm lè a, li voye mesaje nan tout branch fanmi Izrayèl yo pou di yo: Lè n'a tande twonpèt yo kònen, n'a fè konnen yo fè Absalon wa lavil Ebwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 11, text = "Te gen desan (200) moun lavil Jerizalèm ki te pati avèk Absalon. Se Absalon ki te envite yo. Yo te byen kontan pati avè l', men yo pa t' konn anyen nan zafè konplo a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 12, text = "Antan Absalon t'ap ofri bèt pou Seyè a, li voye lavil Gilo al chache Achitofèl ki te yonn nan konseye David yo. Konplo a t'ap pran fòs. Patizan Absalon yo t'ap vin pi plis.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 13, text = "Yon mesaje vin di David: -Moun peyi Izrayèl yo ap mache avèk Absalon, yo dakò avè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 14, text = "Se konsa David rele moun pa l' yo ki te avè l' lavil Jerizalèm, li di yo: -Se pou n' prese mete deyò si nou vle chape anba men Absalon. Ann fè vit kite lavil la. Si se pa sa, talè l'ap sou nou. L'ap fè nou pase pa nou, l'ap touye dènye moun nan lavil la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 15, text = "Patizan wa yo reponn: -Wi, monwa. Nenpòt kisa ou vle nou fè, n'ap fè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 16, text = "Wa a pran tout fanmi l', li pati apye. Li kite dis nan fanm kay li yo pou okipe palè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 17, text = "Wa a leve pati kite lavil la ansanm ak tout moun pa l' yo. Lè yo rive devan dènye kay la, yo fè yon kanpe.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 18, text = "Tout chèf li yo te kanpe bò kote l'. Yo kite tout gad pèsonèl wa a, ki vle di sòlda keretyen yo ak sòlda peletyen yo pase devan. Te gen sisan (600) sòlda moun lavil Gat ki te kite peyi yo vin jwenn David lavil Jerizalèm. Yo vin ap pase devan li tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 19, text = "Wa a rele Itayi, chèf moun lavil Gat yo, li di l' konsa: -Poukisa ou prale ak nou tou? Tounen non, monchè. Rete ak lòt wa a. Ou pa moun peyi a. Se kouri ou kouri vin kache isit la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 20, text = "Ou pa gen lontan depi ou rive. Poukisa jòdi a pou m' fè ou ap mache nan bwa tankou vakabon ansanm avèk nou? Mwen pa menm konnen kote mwen prale. Tounen tounen ou ansanm ak tout moun menm peyi avè ou yo. Mwen mande Seyè a pou l' aji byen avè ou, pou l' pa janm lage ou!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 21, text = "Men Itayi reponn li: -Monwa, mwen fè sèman devan Seyè a ak devan ou, se ou menm m'ap sèvi. Kote ou prale mwen pral avè ou, menm si mwen gen pou m' mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 22, text = "Lè sa a, David di li: -Bon. Ou mèt pran devan nou. Se konsa Itayi, moun lavil Gat la, ale avèk wa a, li menm, tout moun li yo ansanm ak tout fanmi yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 23, text = "Tout moun nan peyi a t'ap rele byen fò lè yo wè David ak moun pa l' yo ap pase ale. David janbe lòt bò ravin Sedwon an ansanm ak tout moun li yo. Yo pran wout ki mennen nan dezè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 24, text = "Zadòk, prèt la, te la tou ansanm ak tout moun fanmi Levi yo ki t'ap pote Bwat Kontra Seyè a. Yo depoze Bwat Kontra a atè. Yo pa leve l' jouk tout rès moun yo fin soti kite lavil la. Abyata, prèt la, te la tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 25, text = "Apre sa, wa a di Zadòk konsa: -Pote Bwat Kontra a tounen nan lavil la. Si Seyè a pran plezi nan mwen, yon jou l'a kite m' tounen pou m' wè bwat la ansanm ak kote l' rete a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 26, text = "Men, si li pa kontan avè m' anko, enben, lè sa a, l'a fè sa li vle avè m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 27, text = "Epi wa a di Zadòk ankò: -Gade! Ou menm ak Abyata, tounen tounen nou lavil Jerizalèm ansanm ak Akimaz, pitit gason ou lan, ak Jonatan, pitit gason Abyata a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 28, text = "Mwen menm, mwen pral tann nou bò larivyè a nan dezè a jouk n'a voye nouvèl ban mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 29, text = "Se konsa Zadòk ak Abyata pote Bwat Kontra a tounen lavil Jerizalèm, yo rete la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 30, text = "David menm moute sou mòn Pye Oliv yo. Li t'ap kriye, li te pye atè, tèt li te kouvri, paske li te nan gwo lapenn. Tout moun ki t'ap mache deyè l' yo te gen tèt yo kouvri tou, yo t'ap kriye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 31, text = "Lè David vin konnen Achitofèl te pran pozisyon ak Absalon nan konplo a, li lapriyè, li di: -Tanpri, Seyè! Fè konsèy Achitofèl yo pase pou pawòl moun fou!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 32, text = "Lè David rive sou tèt ti mòn lan, kote yo konn fè sèvis pou Bondye a, Ouchayi, moun peyi Ak la, vin kontre l', rad sou li dechire, tèt li kouvri ak pousyè tè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 33, text = "David di l' konsa: -Ou p'ap ka fè anyen pou mwen si ou vin avè m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 34, text = "Men, ou ka ede m' anpil si ou tounen lavil Jerizalèm. W'a di Absalon ou pral sèvi l' koulye a menm jan ou te sèvi papa l' nan tan lontan. Lè sa a, w'a ede m' pare tout move kou Achitofèl va gen lide pote m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 35, text = "Zadòk ak Abyata, de prèt yo, va la tou. W'a di yo tou sa w'a tande y'ap di nan palè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 36, text = "Yo gen Akimaz ak Jonatan, pitit gason yo, ak yo. W'a voye yo vin di m' dènye sa w'a tande nan palè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 15, verseNumber = 37, text = "Se konsa, Ouchayi, bon zanmi David la, tounen lavil Jerizalèm. Li antre nan lavil la an menm tan ak Absalon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 1, text = "David te fèk fin kite tèt mòn lan lè li wè Ziba, domestik Mefibochèt la, k'ap vin kontre l'. Li t'ap mennen de bourik byen chaje avèk desan (200) pen, san (100) grap rezen chèch, san (100) pake fwi mi ak yon gwo veso fèt ak po bèt plen diven.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 2, text = "Wa David mande l': -Sa ou pral fè ak tout bagay sa yo? Ziba reponn li: -Bourik yo, se pou wa a ansanm ak fanmi li yo moute. Pen yo ak fwi yo, se pou moun ou yo manje, diven an pou yo bwè lè y'a santi yo bouke nan dezè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 3, text = "Wa a mande l': -Kote mèt ou, Mefibochèt, pitit pitit Sayil la? Ziba reponn: -Li rete lavil Jerizalèm, paske li di li sèten moun peyi Izrayèl yo pral renmèt li baton kòmandman ki te nan men Sayil, granpapa l' la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 4, text = "Wa a di Ziba konsa: -Depi jòdi a, tou sa ki te pou Mefibochèt se pou ou yo ye. Ziba reponn li: -Men mwen lage kò m' nan pye ou, monwa. Mwen mande pou ou toujou kontan avè m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 5, text = "Lè wa David rive bò lavil Bakourim, yon moun fanmi wa Sayil soti lavil la vin kontre l'. Se te Chimeyi, pitit gason Gera a. Antan l'ap vanse sou David, li t'ap joure l', li t'ap ba li madichon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 6, text = "Li konmanse voye wòch sou David ak sou moun pa l' yo, atout pèp la ak sòlda yo t'ap mache sou bò dwat ak sou bò gòch wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 7, text = "Chimeyi t'ap bay David madichon, li t'ap di l': -Ale ou vouzan! Ale ou vouzan! Vakabon! Ansasen!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 8, text = "Ou te pran plas wa Sayil la! Jòdi a Seyè a ap pini ou pou tout moun nan fanmi Sayil ou te sasinen yo. Seyè a renmèt gouvènman an nan men Absalon, pitit gason ou lan. Se konsa pou ou te fini, se ansasen ou ye!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 9, text = "Abichayi, pitit gason Sewouya a, di wa a konsa: -Monwa, poukisa pou ou kite chen mouri sa a ap madichonnen ou konsa? Kite m' janbe lòt bò a al koupe tèt li!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 10, text = "Wa a di Abichayi ansanm ak Joab, frè li a: -Pa antre nan sa ki pa gade nou, tande. Si se Seyè a ki di l' pou l' ban m' madichon, ki moun ki gen dwa mande l' pouki l'ap fè sa?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 11, text = "Apre sa, David pale ak Abichayi ansanm ak tout moun pa l' yo, li di yo: -Gade! Pwòp pitit gason mwen, san mwen, deyò pou l' touye m'. Ale wè pou moun sa a ki soti nan ras Benjamen yo! Kite l' ban m' madichon, si se Seyè a ki di l' ban m' madichon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 12, text = "Nou pa janm konnen, Seyè a va wè nan ki mizè mwen ye. Lè sa a, l'a ban m' benediksyon nan plas madichon l'ap ban m' jòdi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 13, text = "Se konsa, David ale chemen l' avèk tout moun li yo. Chimeyi menm t'ap mache dèyè yo sou flan mòn lan, li t'ap ba yo madichon, li t'ap voye wòch ak pousyè tè sou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 14, text = "Wa a ansanm ak tout pèp la te bouke jouk yo pa t' kapab ankò lè yo rive bò larivyè Jouden. Se la yo rete pran souf.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 15, text = "Absalon antre lavil Jerizalèm ansanm ak tout moun peyi Izrayèl yo. Achitofèl te ansanm ak yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 16, text = "Lè Ouchayi, bon zanmi David la, kontre ak Absolon, li di: -Viv wa a! Viv wa a!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 17, text = "Absalon di l' konsa: -Se konsa ou te bon zanmi David la? Poukisa ou pa t' ale ansanm avè l'?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 18, text = "Ouchayi reponn li: -Ki jan pou m' ta fè sa? Se pou moun Seyè a ansanm ak moun sa yo ak tout moun peyi Izrayèl yo chwazi a mwen ye. Se avè l' pou m' rete.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 19, text = "Lèfini, ki moun pou m' ta sèvi si se pa pitit mèt mwen an? Menm jan mwen te sèvi papa ou, konsa m'a sèvi ou tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 20, text = "Apre sa, Absalon vire bò Achitofèl, li di l' konsa: -Ann antann nou sou sa nou pral fè koulye a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 21, text = "Achitofèl reponn: -Al kouche ak lòt fanm kay papa ou yo, sa li kite dèyè pou okipe palè a. Lè sa a, tout moun nan peyi Izrayèl la va konnen bagay la gate nèt ant ou menm ak papa ou. Konsa, moun ki avè ou yo ap vin pi ankouraje.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 22, text = "Se konsa, yo moute yon tant pou Absalon sou teras sou do palè a. Epi la, devan tout moun peyi Izrayèl yo, Absalon kouche ak fanm kay papa l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 16, verseNumber = 23, text = "Lè sa a, nenpòt konsèy Achitofèl te bay se tankou si se te pawòl Bondye. Ni David ni Absalon te toujou swiv konsèy li yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 1, text = "Apre sa, Achitofèl di Absalon konsa: -Kite m' chwazi douzmil (12.000) sòlda. M'ap pati aswè a menm dèyè David.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 2, text = "M'ap pwofite antan li tou bouke, tou dekouraje a, m'ap atake l', m'ap fè l' pè. Lè sa a, tout moun ki avè l' yo va kraze rak. Se wa a ase m'ap touye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 3, text = "Lèfini, m'ap mennen tout lòt moun yo vin jwenn ou, menm jan yon madan marye tounen vin jwenn mari l'. Se yon sèl moun ou vle yo touye, pa vre. Apre sa, repo pou tout moun.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 4, text = "Koze a te fè Absalon ak tout chèf moun Izrayèl yo plezi.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 5, text = "Absalon di konsa: -Rele Ouchayi, moun peyi Ak la. Ann tande sa li gen pou l' di nou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 6, text = "Lè Ouchayi rive, Absalon di l' konsa: -Men konsèy Achitofèl ban nou. Eske se pou nou fè sa li di nou fè a? Si ou pa dakò, di nou sa pou nou fè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 7, text = "Ouchayi reponn li: -Fwa sa a, konsèy Achitofèl bay la pa bon menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 8, text = "Ou konnen jan papa ou ak moun pa li yo vanyan gason? Koulye a, yo move tankou yon manman lous ki pèdi pitit li. Papa ou se yon sòlda ki gen anpil esperyans nan fè lagè. Li p'ap janm rete pase lannwit menm kote ak moun li yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 9, text = "Koulye a li dwe kache nan yon gwòt osinon yon lòt kote. Premye atak David va fè sou moun ou yo, moun pral konn sa, y'a di: David bat patizan Absalon yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 10, text = "Lè sa a, menm sòlda ki pi vanyan yo, sa ki tankou lyon, ki pa pè anyen yo, pral pèdi kouraj, paske tout moun peyi Izrayèl yo konnen jan papa ou se sòlda ki konn goumen, jan moun pa l' yo se brave danje.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 11, text = "Men konsèy mwen menm m'ap bay: Fè sanble dènye gason nan tout peyi Izrayèl la, depi lavil Dann jouk lavil Bècheba, pou yo tankou grenn sab bò lanmè. Lèfini, ou menm w'a mache alatèt yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 12, text = "Nenpòt kote David ye, n'a tonbe sou li tankou lawouze sou fèy bwa, n'a atake l' anvan menm li konnen sa k'ap rive l'. Nou p'ap kite pesonn chape, ni li, ni yonn nan moun pa l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 13, text = "Si li al kache kò l' nan yon lavil, tout moun Izrayèl yo va pran kòd, y'a mare lavil la, y'a trennen l' al jete anba nan fon an. Yo pa t' kite yon grenn wòch sou tèt mòn kote lavil la te ye a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 14, text = "Absalon ak tout moun peyi Izrayèl yo di: -Konsèy Ouchayi, moun Ak la, pi bon pase pa Achitofèl la. Sa te pase konsa, paske Seyè a te deside pou li pa t' kite yo swiv konsèy Achitofèl la pou malè te ka tonbe sou Absalon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 15, text = "Apre sa, Ouchayi rele Zadòk ak Abyata, prèt yo, li di yo: -Men konsèy Achitofèl te bay Absalon ak chèf fanmi moun Izrayèl yo. Men konsèy mwen menm mwen te ba yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 16, text = "Koulye a, prese voye komisyon bay David. Di li pa rete pase nwit nan plenn dezè a. Se pou l' al pi lwen toujou pou yo pa touye l' ansanm ak moun pa li yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 17, text = "Jonatan, pitit Abyata a, ak Akimaz, pitit Zadòk la, te rete bò sous Lesivèz yo ap tann, paske yo pa t' ka antre nan lavil la pou moun pa t' wè yo. Se yon sèvant ki te konn al pote nouvèl sa k'ap pase ba yo pou yo te ka al avèti wa David.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 18, text = "Men, yon ti gason bare yo, li al di Absalon sa. De mesye yo kouri al kache lakay yon moun ki te rete lavil Bakourim. Nonm lan te gen yon pi nan lakou lakay li. Mesye yo desann al kache ladan l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 19, text = "Madanm nonm lan pran yon gwo dra, li kouvri bouch pi a. Lèfini, li simen grenn pile sou li, konsa pesonn pa wè sa ki anba dra a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 20, text = "Moun Absalon yo vini nan kay la, yo mande madanm lan: -Kote Akimaz ak Jonatan? Madanm lan reponn: -Yo janbe lòt bò dlo a. Mesye Absalon yo chache, men yo pa jwenn yo. Apre sa, yo tounen tounen yo lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 21, text = "Lè yo fin ale, Akimaz ak Jonatan soti nan pi a, y' al pote nouvèl bay wa David. Yo rakonte l' ki konsèy Achitofèl te bay Absalon. Epi yo di l': -Prese janbe lòt bò larivyè Jouden.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 22, text = "Se konsa David leve ansanm ak tout moun ki te avè l' yo, yo janbe lòt bò larivyè Jouden. Lè bajou kase, yo tout te gen tan lòt bò larivyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 23, text = "Lè Achitofèl wè yo pa t' soti pou swiv konsèy li te bay la, li sele bourik li, li tounen lakay li nan peyi l'. Lè li fin regle tout zafè l', li pann tèt li. Se konsa li mouri. Apre sa, yo antere l' nan kavo papa l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 24, text = "Lè Absalon ansanm ak moun li yo rive pou yo janbe lòt bò larivyè Jouden an, David te gen tan rive lavil Manayim.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 25, text = "Absalon te chwazi Amasa pou kòmande lame a nan plas Joab. Amasa sa a te pitit gason Jitra, yon moun fanmi Izmayèl. Manman l' te rele Abigal, pitit fi Nach, sè Sewouya, manman Joab.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 26, text = "Absalon ak moun peyi Izrayèl yo moute tant yo nan peyi Galarad.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 27, text = "Lè David rive lavil Manayim, gen twa moun ki vin jwenn li. Se te Choni, pitit gason Nach, moun lavil Raba, kapital peyi Amon an, Maki, pitit gason Amyèl, moun lavil Lodeba, ak Bazilayi, moun lavil Wogelim nan peyi Galarad.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 28, text = "Twa mesye sa yo te pote bagay pou moun kouche, bòl, kaswòl ak manje pou David ak moun pa l' yo. Te gen ble, lòj, farin, grenn griye, ti pwa ak gwo pwa tout kalite,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 17, verseNumber = 29, text = "siwo myèl, bè, fwomaj lèt bèf, fwomaj lèt mouton. Yonn te di lòt: -Apre tout mache sa a nan dezè a, moun sa yo dwe grangou, yo dwe swaf, yo dwe bouke kont kò yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 1, text = "Wa David sanble tout moun li yo. Li chwazi chèf pou chak rejiman mil sòlda ak pou chak divizyon san sòlda.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 2, text = "Lèfini, li separe lame a an twa pòsyon, yon pòsyon sou lòd Joab, yon pòsyon sou lòd Abichayi, frè Joab la, yon pòsyon sou lòd Itayi, moun lavil Gat. Apre sa, wa a di yo: -Mwen prale avè nou tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 3, text = "Men sòlda yo reponn li: -Non. Ou pa prale avè nou. Sa p'ap di lènmi nou yo anyen si nou kouri pou yo. Si mwatye nan nou mouri, sa p'ap di yo anyen tou. Men ou menm pou kont pa ou, ou vo dimil (10.000) sòlda tankou nou. Se poutèt sa, pito ou rete isit nan lavil la, kote ou ka jwenn konkou pou voye ban nou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 4, text = "W'a reponn yo: -Bon! M'ap fè sa nou wè ki pi bon an. Apre sa, li al kanpe bò pòtay lavil la, pandan lame a t'ap soti, divizyon apre divizyon, rejiman apre rejiman.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 5, text = "Wa a bay Joab, Abichayi ak Itayi lòd sa a: -Tanpri, fè sa pou mwen. Al dousman ak jennonm yo rele Absalon an tande! Tout sòlda yo te tande lè David t'ap bay chèf yo lòd sa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 6, text = "Lame David la soti al goumen ak moun peyi Izrayèl yo. Batay la te fèt nan rakbwa Efrayim lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 7, text = "Lame David la bat lame Absalon an byen bat. Jou sa a, lame Absalon an pèdi venmil (20.000) sòlda.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 8, text = "Batay la gaye nan tout peyi a. Jou sa a, te gen plis moun ki mouri nan rakbwa a pase nan batay la menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 9, text = "Absalon al kontre ak kèk sòlda nan lame David la. Li te moute sou yon milèt. Antan l'ap pase anba yon gwo pyebwa, cheve li yo al pran nan yon branch, milèt la menm pa rete, li kouri al fè wout li. Absalon rete pandye anlè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 10, text = "Yonn nan moun David yo wè sa, li al bay Joab nouvèl la. Li di li: -Mwen wè Absalon pandye nan yon pyebwa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 11, text = "Joab di nonm lan: -Ou wè l'? Poukisa ou pa touye l' la menm? M' ta fè ou kado dis pyès an ajan ak yon sentiwon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 12, text = "Men nonm lan reponn Joab: -Ou ta mèt ban mwen mil (1000) pyès an ajan la nan pla men m', mwen pa t'ap leve men m' sou pitit gason wa a. Nou tout nou te tande lòd wa a te ba ou ansanm ak Abichayi ak Itayi. Li te di: Tanpri, fè sa pou mwen. Pa kite anyen rive Absalon, pitit mwen an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 13, text = "Si m' te pran pòz mwen pa t' tande anyen, epi m' te touye l', wa a t'ap toujou konn sa. Paske li toujou konn tou sa k'ap pase. Lè sa a, ou pa ta janm pran defans mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 14, text = "Joab di li: -M'ap pèdi twòp tan la a avè ou. Li pran twa baton ak pwent yo byen fèt, li al plante yo nan kè Absalon ki te vivan toujou kote li te pandye nan pyebwa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 15, text = "Apre sa, dis jenn sòlda ki t'ap pote zam Joab yo tonbe sou Absalon, yo fin touye l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 16, text = "Lèfini, Joab fè kònen twonpèt la pou yo sispann batay la. Se konsa sòlda David yo kite rès sòlda Izrayèl yo al fè wout yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 17, text = "Yo pran kadav Absalon an, yo jete l' nan yon twou nan rakbwa a. Lèfini, yo kouvri l' ak yon gwo pil wòch. Tout rès moun peyi Izrayèl yo te kouri al lakay yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 18, text = "Depi anvan l' te mouri, Absalon te fè bati yon bèl kavo pou li nan fon Wa a, paske li t'ap di li pa t' gen pitit gason pou leve non li. Jouk jòdi a yo rele kavo a moniman Absalon an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 19, text = "Akimaz, pitit gason Zadòk la, di Joab konsa: -Kite m' kouri al fè wa a konnen jan Seyè a rann li jistis, jan li delivre l' anba men lènmi l' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 20, text = "Joab reponn li: -Non. Jòdi a pa gen bon nouvèl pou ou pote. Yon lòt jou va gen bon nouvèl pou ou pote. Men jòdi a, ou p'ap pote ankenn nouvèl bay wa a, paske se pitit gason wa a menm ki mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 21, text = "Joab rele yon sòlda, moun peyi Letiopi, li di l': -Ou menm, al rakonte wa a tou sa ou te wè ak je ou. Sòlda a bese tèt devan Joab. Lèfini, li kouri, li ale.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 22, text = "Akimaz menm t'ap kenbe se pou l' ale, li di: -Nenpòt sa ki rive m', kite m' ale pote nouvèl la tou dèyè moun Letiopi a. Joab mande l': -Poukisa ou vle fè sa, pitit mwen? Yo p'ap ba ou anyen pou yon nouvèl konsa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 23, text = "Akimaz reponn: -Sa pa fè anyen. Mwen vle ale. Lè sa a, Joab di l': -Ale non! Se konsa Akimaz kouri ale, li pran wout ki pase nan plenn Jouden an, li pran devan moun peyi Letiopi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 24, text = "David menm te chita ant pòtay deyò a ak pòtay anndan an. Yon faksyonnè te moute sou teras anwo miray la, li te kanpe sou tèt pòtay la. Li leve je l', li wè yon nonm ki t'ap kouri vini.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 25, text = "Li rele pou avèti wa a. Wa a di l': -Si li pou kont li, se bon nouvèl l'ap pote. Mesaje a t'ap pwoche toujou", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 26, text = "lè faksyonnè a wè yon lòt moun ki t'ap kouri vini tou. Li pale ak nonm ki t'ap fè pòs bò pòtay la, li di l' konsa: -Men yon lòt moun k'ap vini pou kont li tou. Wa a reponn: -Sa a tou, se bon nouvèl l'ap pote.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 27, text = "Faksyonnè a pran ankò: -Sou jan l'ap kouri a, gen lè premye a se Akimaz, pitit gason Zadòk la. Wa a di: -Se yon bon gason. Ou mèt sèten se bon nouvèl l'ap pote.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 28, text = "Akimaz pwoche, li di wa a bonjou. Lèfini, li tonbe ajenou devan wa a, li bese tèt li jouk atè, li di: -Monwa, lwanj pou Seyè a, Bondye ou la, paske li lage tout moun ki te leve dèyè ou yo nan men ou!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 29, text = "David mande l': -Ban m' nouvèl ti Absalon an non. Li byen? Akimaz reponn li: -Monwa, lè Joab, moun pa wa a, te voye m' lan, mwen wè te gen yon gwo kouri. Men, m' pa konnen sa ki te genyen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 30, text = "Wa a di l': -Bon. Kanpe bò la a. Tann mwen. Akimaz mete kò l' sou kote, li rete ap tann.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 31, text = "Apre sa, nonm peyi Letiopi a vin rive. Li di wa a: -Monwa, mwen gen bon nouvèl pou ou! Jòdi a, Seyè a rann ou jistis. Li wete ou anba men tout moun ki te leve dèyè ou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 32, text = "Wa a mande l': -Ban m' nouvèl ti Absalon an non. Li byen? Nonm peyi Letiopi a reponn, li di l': -Se pou sa ki rive jenn gason sa a rive tout lènmi monwa yo ansanm ak tout lòt moun k'ap leve dèyè ou pou fè ou mal.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 18, verseNumber = 33, text = "Lè wa a pran nouvèl la, sa te twòp pou li. Li moute nan chanm li anwo sou tèt pòtay la pou l' kriye. Antan li prale konsa, li t'ap rele: -Absalon! Absalon, pitit mwen! Absalon! Poukisa se pa mwen ki te mouri nan plas ou! Woy! Absalon, pitit mwen! Absalon, pitit mwen!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 1, text = "Yo voye di Joab jan wa a t'ap kriye, jan li te pran lapenn pou Absalon ki mouri a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 2, text = "Jou sa a, sòlda David yo pa t' fè fèt pou genyen yo genyen batay la. Yo tout te kagou, paske yo te pran nouvèl jan wa a te nan gwo lapenn pou lanmò pitit li a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 3, text = "Yo antre nan lavil la san fè ankenn bri, tankou sòlda ki wont paske yo kouri pou lagè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 4, text = "Wa a menm te kouvri tèt li, li t'ap rele: -Woy! Gason m' lan! Absalon, pitit gason m' lan! Absalon, pitit gason m' lan!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 5, text = "Joab al jwenn wa a nan chanm li, li di l' konsa: -Jan ou fè sa jòdi a ou fè tout sòlda ou yo wont. Yo menm ki te sove lavi ou ansanm ak lavi pitit gason ak pitit fi ou yo, lavi madanm ak fanm kay ou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 6, text = "Ou moutre jan ou renmen moun ki rayi ou, men ou pa vle wè moun ki renmen ou. Ou fè wè jan chèf lame ak sòlda k'ap goumen pou ou yo pa di ou anyen. Jòdi a mwen wè monwa ta pi kontan si Absalon te vivan, epi nou tout nou te mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 7, text = "Koulye a, monwa, leve non! Al pale ak moun pa ou yo pou ankouraje yo. Si ou pa fè sa, mwen fè sèman devan Bondye, denmen maten p'ap gen yon moun k'ap kanpe avè ou ankò. Malè sa a pral pi rèd pase tout malè ki janm tonbe sou ou depi ou te jenn gason rive jounen jòdi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 8, text = "Wa a leve vre, li vin chita bò pòtay lavil la. Lè sòlda yo vin konn sa, yo tout vin sanble bò kote l'. Moun peyi Izrayèl yo menm te kouri ale chak moun lakay yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 9, text = "Nan tou peyi Izrayèl la, moun t'ap diskite, yo t'ap di: -Wa David te delivre nou anba men lènmi nou yo. Li te sove nou anba men moun peyi Filisti yo. Men koulye a, li kouri kite peyi a poutèt Absalon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 10, text = "Nou te fè /seremoni pou mete Absalon wa peyi a. Men li mouri nan lagè. Sa ki kenbe nou koulye a pou nou fè wa David tounen ankò?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 11, text = "Antan wa a lakay li, li vin konnen tou sa pèp la t'ap di. Lamenm, li voye yon mesaj bay Zadòk ak Abyata, li di yo: -Pale ak chèf fanmi moun peyi Jida yo. Mande yo poukisa se pa yo menm premye moun ki chache fè wa a tounen lakay li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 12, text = "Di yo se fanmi m' yo ye, menm ras avè m'. Poukisa se yo menm dènye moun ki pou fè m' tounen nan palè a?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 13, text = "n'a pale ak Amasa, n'a di l' pou mwen se fanmi m' li ye. Depi jòdi a, mwen mete l' alatèt lame mwen an nan plas Joab. Si mwen pa kenbe pawòl, se pou Bondye ban m' pi gwo pinisyon ki genyen!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 14, text = "Lè tout moun peyi Jida yo tande pawòl David yo, yo tonbe dakò ak li. Yo mete tèt yo ansanm, yo voye di l': -Ou mèt tounen ansanm ak tout moun pa ou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 15, text = "Wa a leve, li pran wout pou l' tounen. Li rive bò larivyè Jouden an. Tout moun peyi Jida yo, bò pa yo, kite lavil Gilgal, y' al kontre wa a. Yo ede l' janbe larivyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 16, text = "Se konsa yon nonm nan branch fanmi Benjamen an, Chimeyi, pitit Gera a, moun lavil Baourim, te kouri al kontre wa David bò larivyè Jouden an ansanm ak yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 17, text = "Te gen mil (1000) gason nan branch fanm Benjamen an avè l'. Ziba, domestik fanmi Sayil la, te la tou ansanm ak kenz pitit gason l' yo ak vin moun k'ap travay avèk li yo. Yo tout kouri al kontre wa a bò larivyè Jouden an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 18, text = "Yo janbe larivyè a, yo ede moun wa yo janbe pas la. Yo fè tou sa wa a te mande yo fè. Lè wa a fè sa pou l' janbe tou, Chimeyi lage kò l' atè devan wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 19, text = "Li di l' konsa: -Monwa, tanpri! Pa kenbe m' nan kè! Bliye sa m' te fè ou jou ou t'ap kite lavil Jerizalèm lan. Tanpri, pa kenbe m' nan kè!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 20, text = "Mwen konnen sa m' te fè a te mal, monwa. Ou wè jòdi a, premye moun nan tout branch fanmi Jozèf la ki kouri vin resevwa ou, se mwen menm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 21, text = "Lè sa a, Abichayi, pitit gason Sewouya a, pale, li di konsa: -Sa pa ka anpeche yo touye Chimeyi, paske li te bay moun Bondye te chwazi pou wa a madichon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 22, text = "Men David reponn li: -Pa antre nan koze a. Sa pa gade ou, pitit Sewouya! Poukisa jòdi a ou vle kenbe tèt avè m'? Mwen pa vle yo touye pesonn nan moun peyi Izrayèl yo, paske jòdi a mwen konnen se mwen menm ki wa peyi Izrayèl la vre.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 23, text = "Apre sa, wa a di Chimeyi konsa: -Mwen fè ou sèman, yo p'ap touye ou!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 24, text = "Mefibochèt, pitit pitit Sayil la, te vin kontre wa a tou. Depi jou wa David te kite lavil Jerizalèm lan jouk jou li te tounen san danje san malè a, Mefibochèt pa t' koupe bab li, ni li pa t' lave pye l', ni li pa t' lave rad sou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 25, text = "Lè Mefibochèt rive lavil Jerizalèm pou li al resevwa wa a, wa a di l': -Mefibochèt, poukisa ou pa t' pati ansanm avè m'?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 26, text = "Mefibochèt reponn li: -Monwa, se domestik mwen an ki woule m'. Ou konnen m' enfim. Mwen te mande domestik mwen an pou l' te sele fenmèl bourik mwen an pou m' te ka ale ansanm avèk monwa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 27, text = "Domestik la al ba ou manti sou mwen. Men, monwa, mèt mwen, ou tankou yon zanj Bondye. Ou mèt fè sa ou vle avè m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 28, text = "Tout moun nan fanmi Sayil, granpapa m' lan, te merite pou ou te touye yo vre. Men monwa, ou ban m' dwa pou m' manje sou menm tab avè ou. Mwen pa gen dwa mande monwa ankenn lòt favè ankò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 29, text = "Wa reponn li: -Ou pa bezwen di anyen ankò! Mwen pran desizyon m' deja. W'a antann ou ak Ziba pou nou pataje tè Sayil yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 30, text = "Mefibochèt di wa a: -Ziba te mèt pran tout pou li. Sa ki pi enpòtan pou mwen, se wè pou m' wè wa a tounen san danje san malè nan palè li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 31, text = "Bazilayi, moun lavil Gilgal, te desann soti lavil Wogelim rive larivyè Jouden ansanm ak wa a. Li janbe lòt bò larivyè a ansanm ak wa a. Lè li fin janbe, li di wa a orevwa pou l' te tounen lakay li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 32, text = "Bazilayi te yon vye granmoun, li te gen katrevenzan. Li te rich anpil. Se li menm ki te bay wa a tout pwovizyon li te bezwen lè wa a te lavil Manayim.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 33, text = "Wa a di l' konsa: -Ann ale ansanm avè m' lavil Jerizalèm non. M'a pran swen ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 34, text = "Men Bazilayi reponn li: -Monwa, mwen pa rete anpil tan ankò pou m' viv. M' pa wè poukisa pou m' ale ansanm avè ou lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 35, text = "Mwen deja gen katreven lanne sou tèt mwen. Anyen pa di m' anyen ankò. M' pa pran gou ni sa m'ap manje, ni sa m'ap bwè. M' pa tande vwa gason ak fi k'ap chante yo ankò. M' pral tounen yon chay pou monwa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 36, text = "Epitou, mwen pa merite tout rekonpans sa a. Se annik yon ti bout chemen m' te vle fè avè ou lòt bò larivyè Jouden an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 37, text = "Tanpri, kite m' tounen lakay mwen. Konsa, m'a mouri toupre tonm fanmi mwen. Men Chimkam, pitit mwen, ki va sèvi ou. Ou mèt pran l' avè ou, monwa. W'a fè sa ou wè ki pi bon pou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 38, text = "Wa a reponn li: -Bon. M'ap pran l' avè m'. M'a fè pou li tou sa ou menm w'a wè ki bon pou li. Nenpòt kisa w'a mande m', m'a fè l' pou ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 39, text = "Apre sa, tout moun yo janbe lòt bò larivyè Jouden an. Lè wa a fin janbe, li bo Bazilayi, li rele benediksyon Bondye sou li. Bazilayi tounen lakay li apre sa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 40, text = "Tout moun peyi Jida yo ak mwatye nan moun peyi Izrayèl yo janbe lòt bò larivyè Jouden an ansanm ak wa a. Wa a desanm lavil Gilga. Chimkam te ale avè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 41, text = "Lè sa a, moun peyi Izrayèl yo al jwenn wa a, yo di l' konsa: -Monwa, poukisa frè nou yo, moun peyi Jida yo, te vin pran ou, yo fè ou janbe larivyè Jouden ansanm ak tout fanmi ou ak tout moun pa ou yo?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 42, text = "Moun Jida yo reponn: -Nou fè l' paske wa a pi fanmi moun Jida yo pase li fanmi moun Izrayèl yo. Sa ki gen la a atò pou nou fache? Li pa janm peye manje pou nou ki fanmi l', ni li pa janm fè nou kado anyen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 19, verseNumber = 43, text = "Lamenm, moun peyi Izrayèl yo reponn moun peyi Jida yo: -Nou gen dis fwa plis dwa pase moun Jida yo sou wa a, menm si se fanmi yo li ye. Poukisa nou menm moun Jida yo, nou meprize moun peyi Izrayèl yo konsa? Pa bliye se nou menm premye moun ki te pale koze fè wa a tounen an. Men moun peyi Jida yo pale pi fò, yo fèmen bouch moun peyi Izrayèl yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 1, text = "Nan lavil Gilgal te gen yon nonm yo te rele Cheba, pitit Bikri, nan branch fanmi Benjamen an. Se te yon vakabon. Li manche twonpèt li, li rele pèp la, epi li di yo byen fò: -Nou pa gen anyen pou nou wè ak David! Nou pa bezwen anyen nan zafè pitit Izayi a! Ann al lakay nou, nou menm moun peyi Izrayèl yo!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 2, text = "Se konsa moun peyi Izrayèl yo vire do bay David pou yo swiv Cheba, pitit Bikri a. Men, moun peyi Jida yo rete ak David. Yo swiv li depi larivyè Jouden rive lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 3, text = "Lè David rive nan palè li lavil Jerizalèm, li pran dis fanm kay li te kite pou okipe palè a, li fèmen yo nan yon kay apa ak moun pou siveye yo. Li ba yo tou sa yo bezwen, men li pa janm kouche ak yo yonn ankò. Yo rete fèmen la tout rès lavi yo, tankou fanm ki pèdi mari yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 4, text = "Apre sa, wa a pale ak Amasa, li di l' konsa: -M' ba ou twa jou pou ou sanble tout mesye Jida yo. Apre sa, w'a vin ak yo devan m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 5, text = "Amasa pati al avèti mesye Jida yo. Men, li pa tounen dat wa a te ba li pou l' te tounen an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 6, text = "Wa a rele Abichayi, li di l' konsa: -Cheba pral ban nou plis traka pase Absalon. Pran kòmandman lame mwen an. Pati dèyè l' anvan li gen tan jwenn yon lavil ak gwo ranpa pou l' chape anba men nou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 7, text = "Se konsa sòlda Joab yo, keretyen yo ak peletyen yo ak tout lòt vanyan sòlda ki te nan lame wa a kite lavil Jerizalèm ak Abichayi, yo pati dèyè Cheba.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 8, text = "Lè yo rive bò gwo wòch ki nan lavil Gibeyon an, Amasa vin kontre ak yo. Joab te gen rad batay li sou li ak yon nepe nan djenn li mare nan ren l'. Joab vanse devan l'. Nepe a soti nan djenn lan, li tonbe atè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 9, text = "Joab di Amasa: -Ban m' nouvèl ou non, zanmi. Epi li kenbe l' nan bab ak men dwat li pou l' bo li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 10, text = "Amasa menm pa fè atansyon lòt nepe Joab te kenbe nan men gòch li a. Joab djage l' nan vant. Tout trip li soti deyò. Li mouri la menm. Konsa, Joab pa t' bezwen ba li yon dezyèm kou. Apre sa, Joab ak Abichayi, frè l' la, pati dèyè Cheba.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 11, text = "Yonn nan sòlda Joab yo te kanpe bò kadav Amasa a. Li pran rele byen fò: -Tout moun ki pou Joab ak David, se pou yo swiv Joab!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 12, text = "Men, kadav Amasa a, tou plen san, te blayi nan mitan wout la. Lè sòlda Joab la wè chak fwa yon moun rive devan kadav la li rete, li pran kadav Amasa a, li trennen l' nan yon jaden sou kote wout la, li voye yon rad sou li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 13, text = "Lè li wete kadav la nan mitan wout la, tout lame a pase, yo pati ak Joab dèyè Cheba, pitit Bikri a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 14, text = "Cheba bò pa l' menm te pase nan tout peyi ki pou branch fanmi Izrayèl yo, li rive lavil Abèl-Bèt Maka. Tout moun fanmi Bikri yo te sanble dèyè l', yo swiv li nan lavil la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 15, text = "Sòlda Joab yo vin rive devan Abèl-Bèt Maka. Yo sènen lavil la, yo anpile ranblè nan pye gwo miray deyò a pou yo te ka anvayi lavil la. Apre sa, yo pran fouye anba miray la pou fè l' tonbe.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 16, text = "Te gen yon fanm nan lavil la ki te gen bon konprann. Li rete sou miray la, li di: -Ey! Ey! Tanpri, koute sa m'ap di nou! Al di Joab pou l' pwoche bò isit la. Mwen ta renmen fè yon ti pale avè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 17, text = "Joab vin rive. Fanm lan mande l': -Se ou menm ki Joab la? Joab reponn: -Wi, se mwen menm. Fanm lan di l': -Se sèvis m'ap rann ou. Koute sa m'ap di ou. Joab reponn: -M'ap koute ou, wi.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 18, text = "Fanm lan di konsa: -Nan tan lontan yo te konn di: Depi ou bezwen konnen kichòy, desann lavil Abèl, al mande la. Se konsa moun te toujou regle zafè yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 19, text = "Lavil nou se yonn nan lavil peyi Izrayèl yo kote ki pa gen dezòd. Lèfini, li pa janm vire do bay wa a. Poukisa w'ap chache detwi l'? Se kraze ou vle kraze sa ki pou Seyè a?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 20, text = "Joab reponn li: -Sa ou kwè a se pa sa! Se pa t' nan lide m' ni pou m' te kraze, ni pou m' te detwi lavil nou an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 21, text = "Se pa dèyè sa nou ye. Gen yon nonm yo rele Cheba, pitit gason Bikri a. Se moun mòn Efrayim li ye. Li pran lezam kont wa David. Si ou lage nonm sa a nan men m', m'ap vire do m' kite lavil la an repo. Fanm lan reponn li: -N'ap voye tèt li jete lòt bò miray la ba ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 22, text = "li al pale ak moun lavil yo, li di yo sa li gen lide fè. Yo koupe tèt Cheba, yo voye l' jete lòt bò miray la bay Joab. Joab fè kònen twonpèt la pou bay sòlda li yo siyal pou yo kite lavil la al fè wout yo lakay yo. Joab menm tounen lavil Jerizalèm al jwenn wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 23, text = "Joab te kòmandan tout lame pèp Izrayèl la. Benaja, pitit Jeyojada, te kòmandan keretyen yo ak peletyen yo, gad pèsonèl wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 24, text = "Adoram te reskonsab kòve yo. Jeozafa, pitit gason Aliyoud la, te reskonsab achiv wa a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 25, text = "Cheva te sekretè gouvènman an. Zadòk ak Abyata te prèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 20, verseNumber = 26, text = "Te gen yon nonm yo te rele Ira, moun lavil Jayi, ki te prèt wa David tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 1, text = "Sou rèy wa David, vin gen yon gwo grangou pandan twazan yonn apre lòt. Lè sa a, David al mande Seyè a sa k'ap pase. Seyè a reponn li: -Se krim Sayil ak fanmi l' yo te fè ki lakòz grangou sa a, paske yo te sasinen moun lavil Gabawon yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 2, text = "Moun lavil Gabawon yo pa t' fanmi moun Izrayèl yo. Se yon ti rès nan moun peyi Amori moun Izrayèl yo te pran angajman yo t'ap toujou pwoteje. Men, Sayil te sitèlman cho pou defann enterè moun fanmi Izrayèl ak fanmi Jida yo, li te soti pou l' te detwi yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 3, text = "Se konsa David voye chache yo, li mande yo: -Kisa m' ka fè pou nou? Ki jan pou m' repare tou sa nou sibi pou nou ka rale benediksyon sou pèp Seyè a?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 4, text = "Yo reponn li: -Sa nou gen pou n' regle ak Sayil ansanm ak rès fanmi li an, se pa yon keksyon lò ak ajan, ni nou pa ta renmen touye pesonn nan peyi Izrayèl. David mande yo: -Manyè di m' sa nou vle m' fè pou nou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 5, text = "Yo reponn li: -Sayil te soti pou disparèt nou. Li te fè lide pou l' te touye nou nèt pou l' pa kite yonn nan nou vivan nan tout peyi Izrayèl la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 6, text = "Enben, renmèt nou sèt gason nan fanmi li an pou nou ka pann yo devan Seyè a nan lavil Gabawon, lavil Sayil la menm, nonm Seyè a te chwazi pou wa a. David reponn yo: -M'ap ban nou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 7, text = "David pa ba yo Mefibochèt, pitit Jonatan an, pitit pitit Sayil la, poutèt sèman li menm ak Jonatan, pitit Sayil la, yo te fè devan Bondye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 8, text = "Men, li pran Amoni ak Mefibochèt, de pitit gason Rispa, pitit Ayi a, te fè pou Sayil, ansanm ak senk pitit gason Merab, pitit Sayil la, te fè pou Adriyèl, pitit gason Bazilayi, moun lavil Meola a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 9, text = "Li lage yo nan men moun Gabawon yo ki pann yo sou yon ti mòn devan Seyè a. Yo tou lesèt mouri ansanm. Lè sa a, se te fen sezon prentan, yo te fèk konmanse rekòt lòj la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 10, text = "Apre sa, Rispa, pitit Ayi a, pran yon rad sak, li vlope kò l' ladan l', li al chita sou wòch kote kadav yo te ye a. Li rete la depi nan konmansman rekòt la jouk sezon lapli a rive. Lajounen li t'ap chase zwazo ki te vle vin poze sou kadav yo. Lannwit li t'ap kouri dèyè bèt nan bwa ki te vle vin devore yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 11, text = "Y' al rapòte bay David sa Rispa, yonn nan fanm kay Sayil yo, t'ap fè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 12, text = "David al pran zosman Sayil ansanm ak zosman Jonatan nan men moun lavil Jabès yo nan peyi Galarad. (Moun sa yo te al vòlò kadav Sayil ak Jonatan sou plas piblik lavil Bèt-Chean kote moun Filisti yo te pann yo lè yo te fin touye Sayil sou mòn Gilboa a.)", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 13, text = "David pran zosman Sayil ansanm ak zosman Jonatan yo, li ranmase zosman sèt mesye yo te pann yo tou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 14, text = "Lèfini, yo antere yo ansanm ak zosman Sayil ak zosman Jonatan yo nan tonm Kich, papa Sayil la, lavil Zela nan pòsyon peyi ki pou branch fanmi Benjamen yo. Yo fè tou sa wa a te bay lòd fè a. Apre sa, Bondye tande lapriyè yo pou peyi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 15, text = "Lagè pete ankò ant moun Filisti yo ak moun peyi Izrayèl yo. David desann ak sòlda li yo, li al goumen ak moun Filisti yo. Pandan y'ap goumen konsa, David santi l' bouke.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 16, text = "Yon potorik gason bèl wotè yo te rele Ichbibenòb, moun laras Arafa yo, fè lide pou l' touye David. Li te gen yon frenn an kwiv ki te peze sèt liv edmi konsa ak yon nepe tou nèf mare nan ren li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 17, text = "Men, Abichayi, pitit gason Sewouja a, vin pote wa a sekou. Li atake moun Filisti a, li touye l'. Lè sa a, moun David yo fè wa a pwomèt pou li pa janm vin nan lagè avè yo ankò. Yo di l': -Ou se espwa pèp Izrayèl la. Nou pa vle pèdi ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 18, text = "Apre sa, te gen yon lòt batay ankò avè moun Filisti yo lavil Gòb. Lè sa a, Sibekayi, moun lavil Ousa, touye Saf, yon lòt potorik gason nan ras moun Arafa yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 19, text = "Pandan yon lòt batay avèk moun Filisti yo ankò nan menm lavil Gòb la, Elanan, pitit gason Jari, moun lavil Betleyèm, touye Golyat, yon moun lavil Gat. Frenn Golyat la te gen yon manch menm gwosè ak yon gwo manch pilon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 20, text = "vin gen yon lòt batay ankò lavil Gat. Lè sa a, te gen yon sòlda bèl wotè ki te gen sis dwèt nan chak men, sis zòtèy nan chak pye. Se te yonn nan ras moun Arafa yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 21, text = "Li t'ap pase moun pèp Izrayèl yo nan betiz. Jonatan, pitit gason Chimeya, frè David la, touye l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 21, verseNumber = 22, text = "Kat sòlda peyi Filisti sa yo te moun bèl wotè, potorik gason, nan ras moun Arafa yo lavil Gat. David ak moun pa li yo touye yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 1, text = "Lè Seyè a te fin delivre David anba men Sayil ak anba men tout lènmi li yo, David chante chante sa a pou Seyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 2, text = "Li di konsa: -Seyè, se ou menm ki twou wòch kote m' kache a. Se ou menm ki sèvi m' ranpa. Se ou menm ki delivre m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 3, text = "Ou se Bondye mwen, se ou menm ki pwoteje m'. Se nan ou mwen mete tout konfyans mwen. Se ou ki tout defans mwen. Se fòs ou k'ap sove m'. Se anba zèl ou m' jwenn kote pou m' kache. Se ou ki delivrans mwen. Se ou ki delivre m' anba mechan yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 4, text = "Mwen rele Seyè a, li delivre m' anba lènmi m' yo. Lwanj pou Seyè a!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 5, text = "Lanmò te fin vlope m', mwen te pè lè m' wè tout malè sa yo tonbe sou mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 6, text = "Privye lanmò te tonbe sou mwen yon sèl kou. Kote m' vire, mwen wè lanmò devan m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 7, text = "Nan mizè mwen te ye a mwen rele Seyè a, Mwen mande Bondye mwen sekou. Kote l' chita lakay li a, li tande vwa mwen. Rèl mwen rive jouk nan zòrèy li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 8, text = "Lè sa a, latè pran tranble, li souke. Fondasyon syèl la pran tranble. Yon sèl frison pran yo, paske Bondye te an kòlè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 9, text = "Lafimen t'ap soti nan twou nen li. Yon gwo flanm dife ak moso chabon tou limen t'ap soti nan bouch li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 10, text = "Li bese syèl la, li desann ak yon gwo nwaj nwa anba pye li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 11, text = "Li moute sou do yon zanj cheriben, li t'ap vole. Yon kouran van t'ap pouse l' ale.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 12, text = "Li te kache kò l' nan fènwa. Yon gwo nwaj pwès plen dlo te vlope l' toupatou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 13, text = "Anpil chabon dife tou limen t'ap soti nan gwo limyè ki t'ap klere devan li an.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 14, text = "Seyè a pran gwonde nan syèl la. Bondye ki anwo nan syèl la fè tout moun tande vwa li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 15, text = "Li voye flèch li yo, li gaye tout lènmi m' yo, li fè yo tout kouri ak kout zèklè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 16, text = "Lè ou an kòlè, Seyè, van soti ak fòs nan twou nen ou. Lè konsa, moun wè fon lanmè a, fondasyon latè a parèt aklè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 17, text = "Seyè a rete nan syèl la, li lonje men l', li pran m'. Li rale m' soti nan mitan gwo dlo yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 18, text = "Li delivre m' anba gwo lènmi m' yo, anba tout moun sa yo ki te rayi m', epi ki te pi fò pase m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 19, text = "Lè m' te nan tray, yo pwofite atake m'. Men, Seyè a te kenbe m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 20, text = "Li wete m' nan move pa a. Li delivre m' paske li renmen m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 21, text = "Seyè a ban m' sa m' merite, paske li wè m' mache dwat devan li. Li ban m' benediksyon paske li wè mwen inonsan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 22, text = "Mwen te obeyi lalwa Seyè a, mwen pa janm vire do bay Bondye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 23, text = "Mwen fè tou sa ki nan lalwa li, mwen pa janm dezobeyi kòmandman li yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 24, text = "Li konnen mwen pa antò. Mwen kenbe kò m' pou m' pa fè sa ki mal.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 25, text = "Se konsa li ban m' sa m' merite, paske mwen mache dwat devan li, paske li wè mwen inonsan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 26, text = "Ou menm, Seyè, ou kenbe pawòl ou ak moun ki kenbe pawòl yo, ou bon ak moun ki bon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 27, text = "Ou pa fè ipokrit ak moun ki pa fè ipokrit avè ou, men ou malen ak moun ki malen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 28, text = "Ou sove moun ki soumèt yo devan ou. Men, ou annik gade moun ki gen lògèy yo, ou desann yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 29, text = "Seyè, ou se limyè mwen. Se ou ki wete m' nan fènwa kote m' te ye a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 30, text = "Avè ou, mwen fonse sou bann lènmi m' yo ki ame jouk nan dan. Avè ou, mwen eskalade miray ki sèvi yo defans.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 31, text = "Bondye o! Tou sa ou fè bon nèt ale. Ou pa gen de pawòl. Ou pwoteje tout moun ki chache pwoteksyon anba zèl ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 32, text = "Ki moun ki Bondye si se pa Seyè a? Ki moun ki defans nou si se pa Bondye nou an?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 33, text = "Se Bondye ki pwoteje m' avè fòs li. Li fè m' mennen yon lavi san repwòch.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 34, text = "Li asire pye m' tankou pye kabrit, li fè m' mache sou mòn yo san m' pa tonbe.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 35, text = "Li moutre m' jan pou m' goumen. Li ban m' fòs pou m' sèvi ak pi gwo banza ki genyen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 36, text = "Se ou menm, Seyè, ki pwoteje m'. Se ou ki sove m'. Si m' kapab leve kanpe, se paske ou renmen m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 37, text = "Ou pa kite yo bare wout mwen. Mwen pa janm pèdi pye.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 38, text = "Mwen kouri dèyè lènmi m' yo, mwen bat yo. Mwen pa tounen toutan mwen pa fin kraze yo nèt.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 39, text = "Mwen jete yo atè, m' kraze yo, yo pa ka leve. Yo tonbe, mwen mete pye m' sou kou yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 40, text = "Ou ban m' kont fòs pou m' goumen. Ou fè lènmi m' yo mande m' padon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 41, text = "Ou fè yo kouri devan m'. Mwen disparèt tout moun ki rayi m' yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 42, text = "Y'ap mande sekou, men pa gen moun ki ka sove yo. Y'ap rele Seyè a, men li pa reponn yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 43, text = "Mwen kraze yo fè yo tounen pousyè. M' pilonnen yo, m' mache sou yo tankou sou labou nan lari.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 44, text = "Ou delivre m' anba pèp rebèl sa a. Ou fè m' rete chèf pou m' gouvènen tout nasyon yo tou. Pèp mwen pa t' konnen, se yo menm k'ap sèvi m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 45, text = "Moun lòt peyi yo ap achte figi m'. Kou yo tande vwa m', yo obeyi m'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 46, text = "Yo pèdi tout kouraj yo. Yo soti kote yo te kache a, y'ap tranble kou fèy bwa.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 47, text = "Konpliman pou Seyè a! Lwanj pou moun ki pran defans mwen an! Se Bondye ki delivre m', se li menm ki pwoteje m'. Ann fè konnen jan li gen pouvwa!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 48, text = "Se Bondye ki pran revanj mwen. Se li ki mete pèp yo anba pye mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 49, text = "Ou sove m' anba men lènmi m' yo. Ou wete m' anba men moun ki t'ap konbat mwen yo. Ou delivre m' anba ansasen yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 50, text = "Se poutèt sa m'a fè moun lòt nasyon yo konnen ki moun ou ye. m'a chante pou fè lwanj ou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 22, verseNumber = 51, text = "Bondye delivre wa li a anpil fwa. Li moutre jan li pa janm sispann renmen David, moun li chwazi a, ansanm ak pitit pitit li yo pou tout tan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 1, text = "Men dènye pawòl David yo. David, pitit gason Izayi a, te yon nonm Bondye te mete byen wo. Se li menm Bondye Jakòb la te chwazi pou wa. Li te fè bèl chante pou pèp Izrayèl la. Men sa li te di:", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 2, text = "Se lespri Seyè a k'ap pale nan mwen. Se mesaj li k'ap soti nan bouch mwen.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 3, text = "Bondye pèp Izrayèl la pale. Moun k'ap pwoteje pèp Izrayèl la di m' konsa: Chèf k'ap gouvènen san patipri, k'ap gouvènen avèk krentif pou Bondye,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 4, text = "ap tankou solèy k'ap leve byen klere nan maten, nan yon syèl klè san yon ti nwaj ladan l'. L'ap tankou solèy k'ap fè zèb pouse apre lapli.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 5, text = "Se konsa Bondye pral beni tout ras mwen, paske li te pase yon kontra avè m' pou tout tan, yon kontra ki p'ap janm kase, yon pwomès ki p'ap janm chanje. Nan tout sikonstans l'ap fè m' genyen. L'ap ban mwen tou sa mwen vle.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 6, text = "Men, moun ki pa konn Bondye yo, y'ap tankou pikan y'ap voye jete. Pesonn p'ap manyen yo ak men.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 7, text = "Pou manyen yo se pou ou gen yon bout fè osinon yon frenn. Lèfini, ou boule yo nèt nan dife.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 8, text = "Men non vanyan sòlda David yo: Premye a te rele Jochèb Bachebèt, moun lavil Tachemon. Se li menm ki te chèf Twa pi vanyan yo. Pou kont li, li goumen ak frenn li ak witsan (800) moun. Li touye tout yon sèl kou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 9, text = "Dezyèm lan te rele Eleaza, pitit Dodo, pitit yon moun lavil Awoya. Se te yonn nan Twa pi vanyan yo. Yon jou, li menm ak David, y' al atake moun Filisti yo ki te sanble pou goumen. Sòlda pèp Izrayèl yo te kouri pou batay la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 10, text = "Men, li menm, li kenbe tèt ak moun Filisti yo, li touye moun jouk li gen lakranp nan men l'. Li pa t' ka louvri men l' pou l' lage nepe a. Jou sa a, Seyè a goumen byen goumen jouk li touye tout lènmi yo. Apre sa, lame pèp Izrayèl la tounen kote Eleaza te ye a, yo pran tou sa lènmi yo te kite.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 11, text = "Twazyèm lan te rele Chama, pitit gason Age, moun lavil Ara. Yon jou, moun Filisti yo te sanble lavil Lechi, kote ki te gen yon gwo jaden pwa. Sòlda pèp Izrayèl yo t'ap kouri pou moun Filisti yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 12, text = "Men Chama rete kanpe nan mitan jaden pwa a, li kenbe tèt ak moun Filisti yo, li bat yo byen bat. Se konsa Seyè a te goumen byen goumen jouk li touye tout lènmi yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 13, text = "Yon lòt jou, nan sezon rekòt, twa nan gwoup trant yo al jwenn David nan gwòt Adoulam lan. Lame moun Filisti yo te moute kan yo nan plenn Refrayim yo.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 14, text = "Lè sa a, David te nan ti fò a. Yon gwoup moun Filisti te pran lavil Betleyèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 15, text = "Yon sèl anvi pran David, li di konsa: Ki moun ki va fè m' bwè ti gout dlo nan pi ki nan pòtay lavil Betleyèm lan?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 16, text = "Lamenm, twa mesye yo desann nan kan moun Filisti yo, yo pran dlo nan pi ki te nan pòtay lavil Betleyèm lan, yo pote l' vin bay David. Men, David refize bwè dlo a. Li vide l' atè, li ofri l' bay Seyè a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 17, text = "Li di konsa: Seyè, mwen pa gen dwa bwè dlo sa a. Se tankou si m' ta bwè san mesye sa yo ki te riske lavi yo pou al chache l'. Se konsa li derefize bwè dlo a. Se sa twa vanyan sòlda sa yo te fè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 18, text = "Abichayi, frè Joab, pitit Sewouja, te chèf gwoup trant yo. Pou kont li, avèk yon frenn nan men l', li goumen ak twasan (300) moun, li touye yo. Se konsa, tout moun t'ap nonmen non l' nan gwoup trant lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 19, text = "Se non li yo t'ap nonmen pi plis nan Trant yo. Apre sa, li vin chèf yo. Men, li pa janm rive fè sa Twa pi vanyan yo te fè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 20, text = "Benaja, pitit gason Jeojada a, moun lavil Kabseyèl, te pitit pitit yon vanyan sòlda. Li te fè anpil bagay ki fè wè li pa t' manke kouraj. Se li menm ki te touye de pitit Ariyèl yo, moun lavil Moab. Yon jou, lanèj t'ap tonbe, li desann nan yon sitèn dlo pou li touye yon lyon.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 21, text = "Se li menm ki te touye yon moun peyi Lejip, yon potorik gason bèl wotè, ki te gen yon frenn nan men l'. Li menm, li atake l' ak yon baton ase. Li wete frenn lan nan men moun Lejip la epi li touye l' avè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 22, text = "Men sa Benaja, pitit gason Jeojada a, te fè. Se konsa tout moun t'ap nonmen non l' nan gwoup Trant lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 23, text = "Se non li yo t'ap nonmen pi plis nan Trant yo. Apre sa, li vin chèf yo. Men, li pa t' janm rive fè sa twa pi vanyan yo te fè. David te mete l' chèf gad kò li.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 24, text = "Nan gwoup Trant lan te gen ankò: Asayèl, frè Joab la, Elanan, pitit gason Dodo, moun lavil Betleyèm,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 25, text = "Chama ak Elika, moun lavil Awòd,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 26, text = "Elèz, moun lavil Pelèt, Ira, pitit gason Ikèch, moun lavil Tekoa,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 27, text = "Abyezè, moun lavil Anatòt, Mebounayi, moun lavil Oucha,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 28, text = "Salmon, moun lavil Awoya, Marayi, moun lavil Netofa,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 29, text = "Elèb, pitit gason Bana, moun lavil Gibeya nan pòsyon tè ki pou branch fanmi Benjamen yo,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 30, text = "Benaja, moun lavil Piraton, Idayi, moun ravin Gach yo,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 31, text = "Abyalbon, moun lavil Araba, Azmavèt, moun lavil Baawoun,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 32, text = "Elyaba, moun lavil Chalbon, pitit gason Joachenn yo, Jonatan,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 33, text = "Chama, moun lavil Ara, Akiyam, pitit gason Chara, moun lavil Ara,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 34, text = "Elifelèt, pitit gason Asbayi, moun lavil Maka, Elyam, pitit gason Achitofèl, moun lavil Gilo,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 35, text = "Ezarayi, moun lavil Kamèl, Parayi, moun lavil Arab,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 36, text = "Igal, pitit gason Natan, moun lavil Zoba, Bani, moun lavil Gad,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 37, text = "Zelèk, moun lavil Amon, Nakarayi, moun lavil Bewòt, se li menm ki te pote zam Joab, pitit Sewouya a,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 38, text = "Ira ak Garèb, nan fanmi Jetè a,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 23, verseNumber = 39, text = "Ouri, moun lavil Et la. Antou, te gen trannsèt vanyan sòlda.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 1, text = "Yon jou, Seyè a move sou pèp Izrayèl la ankò. Li fè David lakòz malè tonbe sou yo. Seyè a di David al konte konbe moun ki nan peyi Izrayèl ak nan peyi Jida.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 2, text = "Wa a pale ak Joab, kòmandman an chèf lame a, ki te la avè l', li di l' konsa: -Ale nan tout branch fanmi Izrayèl yo, depi lavil Dann nan nò jouk lavil Bètcheba nan sid. Konte mezi moun ki nan pèp la. Mwen vle konnen konbe moun ki gen nan peyi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 3, text = "Men, Joab di wa a: -Monwa, mwen mande Seyè a, Bondye ou la, pou li fè pèp Izrayèl la vin san fwa pi plis pase jan li ye koulye a, lèfini pou monwa ka viv lontan pou wè sa! Men, poukisa, monwa, ou vle konte konbe moun ki nan peyi a?", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 4, text = "Men, wa a pa t' soti pou li chanje lòd li te bay la. Konsa, Joab ak lòt gwo chèf lame yo te blije soumèt yo. Yo soti devan wa a, yo pati, y' al konte konbe moun ki nan peyi Izrayèl la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 5, text = "Yo travèse larivyè Jouden, y' al moute kan yo lavil Awoyè, nan mitan fon an, nan pòsyon tè ki pou branch fanmi Gad la. Apre sa, yo pati pou Jazè bò nan nò.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 6, text = "Y' al lavil Galarad, yo pase lavil Kadès nan pòsyon tè ki pou moun Et yo, jouk yo rive Dann. Yo mache nan tout zòn lan, apre sa y' ale lavil Sidon sou bò lwès.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 7, text = "Lèfini, yo desann nan direksyon sid, yo rive nan Fò Tir la, yo pase nan tout bouk moun Iva yo ak bouk moun Kanaran yo, yo rive Bècheba nan zòn Negèv nan peyi Jida a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 8, text = "Se konsa yo mache nan tout peyi a. Apre nèf mwa ven jou, yo tounen lavil Jerizalèm.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 9, text = "Joab renmèt wa a rapò ki bay kantite moun antou ki te gen nan tout peyi a. Se konsa yo te jwenn witsanmil (800.000) gason ki ka fè lagè epi ki konn sèvi ak nepe nan peyi Izrayèl la ak senksanmil (500.000) nan peyi Jida a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 10, text = "Lè David fin fè konte konbe moun ki gen nan peyi a, konsyans li konmanse repwoche l'. Li di Seyè a: -Lè m' fè sa m' fè a, mwen fè yon gwo peche. Tanpri, Seyè, padonnen m', se sèvitè ou mwen ye. Mwen te aji tankou moun fou.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 11, text = "Nan denmen maten, antan David ap leve sot nan kabann li,", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 12, text = "Seyè a pale ak pwofèt Gad, konseye David la, li di l' konsa: -Al di David mwen ba li twa chatiman pou li menm li chwazi yonn ladan yo. Sa l'a chwazi a se sa m'a fè l'.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 13, text = "Gad vin jwenn li lakay li. Li fè l' konnen mesaj Seyè a te ba li a. Li di l' konsa: -Kisa ou vle? Sèt lanne grangou nan tout peyi a, twa mwa ap kouri devan lènmi ou, osinon twa jou epidemi nan tout peyi a. Al kalkile sou sa pou ou fè m' konnen ki repons pou m' pote bay moun ki voye m' lan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 14, text = "David reponn: -Mwen nan gwo tèt chaje! Men, m' pa vle tonbe anba men lèzòm menm! Pito se Seyè a menm ki pini m', paske li gen bon kè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 15, text = "Se konsa Seyè a voye yon epidemi sou pèp Izrayèl la, li konmanse menm jou maten sa a pou twa jou, jan l' te di a. Depi lavil Dann nan nò rive lavil Bètcheba nan sid peyi a, swasanndimil (70.000) moun nan pèp Izrayèl la mouri.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 16, text = "Lè zanj Seyè a te prèt pou lonje men l' sou lavil Jerizalèm pou detwi l', Seyè a fè lide sispann chatiman an. Li di zanj ki t'ap touye moun yo: -Sispann! kenbe men ou! Lè sa a, zanj lan te gen tan toupre gwo glasi Araounak, moun lavil Jebis la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 17, text = "David wè zanj lan ki t'ap touye moun yo, li pale ak Seyè a, li di l' konsa: -Se mwen menm ki koupab. Se mwen menm ki fè sa ki mal la. Kisa inonsan sa yo fè? Tanpri, se mwen menm ansanm ak fanmi mwen pou ou ta pini!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 18, text = "Men, jou sa a pwofèt Gad al jwenn David, li di l' konsa: -Moute lakay Araounak, moun lavil Jebis la, bati yon lotèl pou Seyè a nan mitan gwo glasi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 19, text = "David koute sa Gad te di l' la, li moute lakay Araounak jan Seyè a te ba li lòd la.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 20, text = "Araounak t'ap gade, li wè wa a ki t'ap vin sou li ansanm ak chèf li yo. Li tonbe ajenou devan wa a, li bese tèt li jouk atè.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 21, text = "Li di l' konsa: -Monwa, sa ki mennen ou isit lakay mwen? David reponn li: -Mwen vin achte anplasman glasi a pou m' bati yon lotèl pou Seyè a, konsa epidemi an va sispann nan peyi a.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 22, text = "Araounak di l' konsa: -Monwa, ou mèt pran l'. Ofri Seyè a sa ou vle. Men bèf sa yo pou ou boule nèt tankou yon ofrann sou lotèl la. Men jouk yo ak bwa kabwa yo pou fè dife.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 23, text = "Araounak bay wa a tout bagay sa yo. Lèfini, li di: -Mwen mande Bondye pou l' asepte ofrann ou an!", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 24, text = "Men wa a reponn li, li di l': -Non. Se achte m'ap achte. Se pou m' peye pou yo. Mwen p'ap pran anyen ki pa koute m' lajan pou m' ofri pou boule nèt pou Seyè a. Se konsa, David achte anplasman glasi a ansanm ak tout bèf yo pou senkant pyès ajan.", bookId = 10),
        Verse(book = "2 Samyèl", chapter = 24, verseNumber = 25, text = "Lèfini, li bati yon lotèl pou Seyè a, li fè ofrann pou boule nèt pou Bondye ak ofrann pou di Bondye mèsi. Seyè a tande lapriyè yo pou peyi a. Epidemi an sispann nan peyi Izrayèl la.", bookId = 10)
    )
}
